import { HistoricalDocument } from '../../types';

export const ordenacoesLivro1TitulosIAX: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-i-a-x',
  title: 'Ordenações Filipinas — Títulos I a X',
  subtitle: 'Do Regedor da Casa da Supplicação',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos I a X do Livro Primeiro das Ordenações Filipinas: de "Do Regedor da Casa da Supplicação" a "Dos Juizes dos feitos del Rei da Fazenda".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-i',
      title: `I. Do Regedor da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-ti-preambulo', number: 'Preâmbulo', text: `Como a Casa da Supplicação seja o maior Tribunal da Justiça de nossos Reinos, e em que as causas de maior importancia se vem a apurar e decidir, deve o Regedor della ter as qualidades, que para cargo de tanta confiança e autoridade se requerem.

Pelo que se deve sempre procurar, que seja homem fidalgo, de limpo sangue, de sã consciencia, prudente, e de muita autoridade, e letrado, se for possível: e sobretudo tão inteiro que sem respeito de amor, odio, ou perturbação outra do animo, possa a todos guardar justiça igualmente.

E assi deve ser abastado de bens temporaes, que sua particular necessidade não seja causa de em alguma cousa perverter a inteireza e constancia com que nos deve servir.

Isso mesmo deve o Regedor ser nosso natural, para que como bom e leal deseje o serviço de nossa pessoa e stado. E assi deve temperar a severidade que seu cargo pede, com paciencia e brandura no ouvir as partes, que os homens de baixo stado, e pessoas miseraveis achem nelle facil e gracioso acolhimento, com que sem pejo o vejam, e lhe requeiram sua justiça, para que suas causas se não percam ao desamparo, mas hajam bom e breve despacho.

E para que o Regedor, que ora he, e qualquer que pelo tempo for, possa melhor cumprir com sua obrigação, e nosso serviço, deve ter sempre ante os olhos nossas Ordenações, e specialmente este seu Regimento, e sempre viva a lembrança do grande cargo, que delle confiamos, para assi ser mais attento e solicito no que deve fazer, e desencarregar nossa consciencia e a sua, e com seu exemplo incitar aos outros Officiaes a nos bem servirem.` },
        { id: 'of1-ti-1', number: '1', text: `Tanto que o Regedor fôr provido do officio, antes que comece a servir ou faça cousa alguma que a elle pertença, lhe será dado juramento pelo Chanceller-mór em nossa presença, naquella fórma que se contém no livro da Relação, em que está scripto: e ao pé do juramento assinará o Regedor com os que se acharem presentes como testemunhas do tal acto.` },
        { id: 'of1-ti-2', number: '2', text: `O Regedor, todos os dias que não fôrem feriados, pela manhã virá á Relação, e fará vir os Desembargadores cedo, porquanto o desembargo dos feitos ha de durar quatro horas inteiras ao menos, passadas pelo relogio de arêa, que será posto na mesa, onde o Regedor stá: o qual tempo se não gastará em praticas, ou occupações outras, não necessarias ao acto, em que stão.` },
        { id: 'of1-ti-3', number: '3', text: `O Regedor elegerá um sacerdote, que todos os dias pela manhã diga Missa no oratorio da Relação, antes de se começar o despacho.` },
        { id: 'of1-ti-4', number: '4', text: `Acabada a Missa, os Desembargadores entrarão logo em despacho; e tanto que entrarem, não consentirá o Regedor, que se levantem das mesas, em que stiverem, para outra alguma parte, salvo por tal necessidade, que se não possa escusar. A qual sendo passada, se tornarão logo a seus assentos e desembargos, de maneira que se não possa perder tempo algum.` },
        { id: 'of1-ti-5', number: '5', text: `Tanto que os Desembargadores começarem de entrar em despacho, o Regedor não consentirá que algum dos Scrivães, Guarda-mór da Relação, Porteiros ou outros quaesquer Officiaes entrem nella, salvo quando fôrem chamados por campainha. E tanto que lhes fôr dito o para que forão chamados, se sahirão, e não se chegarão ás mesas, onde os Desembargadores stiverem despachando. E os Porteiros starão sempre á porta da banda de fôra, para acudirem á campainha. Nem isso mesmo consentirá, que fidalgos, ou outras pessoas, venhão á Relação, salvo quando fôrem chamados.` },
        { id: 'of1-ti-6', number: '6', text: `Para despacho dos feitos, o Regedor repartirá os Desembargadores per todas as mesas dos Officios ordenados, dando a cada mesa os que bem lhe parecer, segundo a qualidade e numero dos feitos; dando porém nos feitos crimes, em que alguma pessoa seja accusada por caso, que provado mereça morte natural, cinco Desembargadores, para com o Juiz do feito serem seis, e não menos. E não sendo os quatro delles conformes em condemnar, ou absolver, metterá mais Desembargadores em numero igual, de modo que nunca se vença, ou condemnar ou absolver, ou remetter ás ordens, ou outro qualquer caso, em que se houver de pôr no feito sentença definitiva, ou interlocutoria, que tenha força definitiva, senão por mais dous votos ao menos. E como quatro Desembargadores fôrem concordes, logo se porá desembargo, e se assinará, e dará á execução. E para mais breve despacho, havemos por bem, que parecendo ao Juiz do feito pelo allegado e provado nelle, que o réo está em absolvição, ou em condemnação, que não exceda cinco annos de degredo, possa pôr o feito com dous Desembargadores, para com elle serem tres. E sendo todos tres conformes em absolvição, ou em pena, que não passe de cinco annos de degredo, se porá sentença. E sendo differentes, dará o Regedor outro Desembargador, ou Desembargadores, em modo que se sejão tres em um acordo, e conforme a elle se porá a sentença.` },
        { id: 'of1-ti-7', number: '7', text: `E mandamos, que nos outros feitos, que em Relação se houverem de despachar, sempre faça por dar os Desembargadores em numero desigual, assi como tres, cinco, sete. E nos feitos crimes, onde não se mereceria morte, postoque provados fossem, o Juiz do feito o poderá despachar com outro Desembargador, para com elle serem dous; e sendo ambos conformes, se porá a sentença, e não o sendo, o Regedor dará outro Desembargador, ou Desembargadores, e como fôrem dous conformes, se porá a sentença, e se dará á execução.` },
        { id: 'of1-ti-8', number: '8', text: `E quando seis Desembargadores fôrem em algum feito de morte, e quatro delles fôrem em voto de condemnar, postoque differentes nas condemnações, e dous em absolver, ponha-se a sentença conforme aos quatro votos, que fôrem em condemnar, reduzindo a maior condemnação á menor, sem o feito ir a mais Desembargadores. E a mesma ordem se guardará, sendo todos os seis em voto de condemnar, postoque differentes nas condemnações, reduzindo os quatro votos da maior condemnação á menor dos ditos quatro votos. E a mesma concordia se terá nos votos dos outros feitos, que per menos Desembargadores houverem de ser despachados.` },
        { id: 'of1-ti-9', number: '9', text: `E sendo caso que os Desembargadores das mesas sejão de votos differentes, de tal maneira que se não possa pôr desembargo, o Regedor fará ajuntar com elles outros, que vejam o feito, sobre que fôr a differença: e o que a maior parte delles juntos acordar, se cumpra. E quando em algum feito, visto per todos os Desembargadores, que presentes fôrem, as vozes fôrem iguaes, o Regedor dará sua voz, e a parte, a que se acostar, prevalecerá; e segundo ella se porá a sentença, e assinará sem postilla, nem outra declaração, per que se possa saber quaes forão em outro parecer; o que não haverá lugar nos feitos, que se despacharem per tenções scriptas nelles, porque nas taes sentenças assinará sómente os que fôrem no parecer, per que a sentença foi vencida e não os outros; porém poderá pôr junto aos seus signaes—pro voto, se em suas tenções não fôrem em todo conformes á sentença, mas sómente em alguma parte.` },
        { id: 'of1-ti-10', number: '10', text: `E se o Regedor vir alguns feitos arduos, assim civeis, como crimes, que em Relação se houverem de despachar, e sentir que ha nelles algumas taes duvidas, que lhe pareça ajuntar mais Desembargadores, que os ordenados ao despacho dos taes feitos, fará ajuntar aquelles, que suspeitos não fôrem, e lhe parecerem necessários, e com elles se desembarguem os ditos feitos, e isto fará, cada vez que necessário lhe parecer. Porém se o despacho do feito pender sobre embargos a algum desembargo, ou sentença, não metterá outros Desembargadores no despacho, senão os que foram no primeiro desembargo, ou sentença. E se lhe parecer que alguns dos ditos Desembargadores são sus- peitos de tal suspeição, que a parte a não possa provar, ou por outra razão, que o mova a nol-o fazer saber, então fará sobrestar no despacho, e nos informará da razão, por que lhe pareceo que se devem metter mais Desembargadores no despacho dos ditos embargos, para Nós nisso provermos como nos bem parecer.` },
        { id: 'of1-ti-11', number: '11', text: `E quando no despacho de alguns feitos, que perante Nós se despacharem em Relação, forem alguns Desembargadores do Paço, e as partes vierem com embargos á sentença, ou despacho, o Regedor dará em lugar delles outros Desembargadores da Casa, que dos ditos embargos conheção.` },
        { id: 'of1-ti-12', number: '12', text: `E não consentirá que feito algum dos que mandamos desembargarem Relação, seja despachado, ou visto pelas casas dos Desembargadores, ou fóra da Relação, mas sómente pelo Juiz que fôr do feito, o qual depois de o ter visto, o levará á Relação, para ahi o despachar segundo seu Regimento. E provando-se que foi despachado pelas casas, ou fóra da Relação, ainda que o despacho seja posto nella, a tal sentença, ou despacho seja nullo, e alem disso o Regedor lho stranhará segundo a qualidade do caso requerer. Porém sendo os feitos primeiro vistos em Relação, se algum Desembargador, por não star bastantemente instruído, os quizer levar para os ver em sua casa, podel-o-ha fazer com licença do Regedor. Os quaes tornará trazer á Relação em um breve termo, que lhe o Regedor assinará, e em outra maneira não.` },
        { id: 'of1-ti-13', number: '13', text: `E os feitos crimes e civeis, que em Relação houverem de ser desembargados, ou em que forem dados certos Juizes para juntamente despacharem, sejam lidos pelo Juiz que fôr de cada hum delles, perante os Desembargadores, que para despacho delles forem deputados. O qual Juiz lerá as inquirições e scripturas, que aos ditos feitos pertencerem. E acabado de ler o feito, o Juiz dará nelle sua voz primeiro, e dahi por diante os outros Desembargadores, que ao feito stiverem; e o que pela maior parte fôr acordado, se cumprirá e dará á execução, sendo porém no despacho dos feitos civeis ao menos tres Desembargadores. E em todos os feitos sobreditos, que em Relação se despacharem pelas mais vozes, como dito he, sempre a sentença, assi definitiva, como interlocutoria, será scripta pelo Juiz do feito, posto que seja em diferente voto; e sera outrosi assinada per todos os que no feito forem, e nelle derem sua voz, posto que alguns delles fossem de contrário parecer, e assinarão sem apostilla, nem outra declaração, per que se possa saber quaes foram de outro voto. E tirando-se a sentença do processo, será assinada pelo dito Juiz do feito sómente; e sendo absente, passará pelo Desembargador, que por elle servir, ou per aquelle, a quem o Regedor o commetter. E se a sentença fôr de qualidade, que quando se tirar do processo, haja de ser assinada per dous Desembargadores, e hum delles fôr absente, passará pelo que presente fôr, e o Scrivão porá no fim da sentença, como não assinou o outro, por ser absente.` },
        { id: 'of1-ti-14', number: '14', text: `E quando alguma das partes tiver suspeição a algum dos Desembargadores ao tempo que o feito se houver de desembargar em Relação, fará disso per palavra informação ao Regedor; e elle com acordo dos outros Desembargadores, que stiverem no despacho do dito feito, a desembargará, como virem que he direito; e segundo per elle com a maior parte dos Desembargadores fôr acordado, assi o mandará cumprir. E achando que he suspeito, commeterá o Regedor o tal feito a outro Desembargador, que suspeito não seja. E emquanto stiverem ás vozes sobre a dita suspeição, o Desembargador, a que fôr posta, se apartará para outra parte, até sobre ella se tomar conclusão.` },
        { id: 'of1-ti-15', number: '15', text: `E quando se houver de commetter algum feito de novo a algum Desembargador, no caso onde não houve suspeição procedida pelo Chanceller, e assi quando os Desembargadores se lançarem de suspeitos, antes de lhes virem com suspeição, ou quando, depois de lha intentarem, se lançam, antes de ser procedida, o Regedor deve commetter os taes feitos a quem lhe bem parecer, que suspeito não seja, não admittindo ás partes roes de pejados, como atéqui se fazia.` },
        { id: 'of1-ti-16', number: '16', text: `E se acontecer algum delicto, que se houver de despachar na Casa da Supplica- ção, em que pareça que se deve proceder summariamente, o Regedor fará ajuntar em Mesa grande seis Desembargadores; e vista a qualidade do caso, e prova, e todo bem considerado, se parecer que se deve nelle proceder summariamente, se procederá. Porém, sendo o reo Cavalleiro, ou d'ahi para cima, e condenado em morte natural, não se fará nelle execução, sem nol-o fazerem saber.` },
        { id: 'of1-ti-17', number: '17', text: `E para os Desembargadores dos Aggravos despacharem todos os feitos, que per bem do seu Regimento hão de despachar em Relação, o Regedor ordenará huma mesa ás terças feiras, quintas e sabbados, para nella despacharem os taes feitos: e na dita mesa os Desembargadores não se occuparão em outra cousa nos taes dias.` },
        { id: 'of1-ti-18', number: '18', text: `Item mandamos que nenhum Desembargador tome petição alguma, em que se requeira mandar ir os autos á Relação; e a parte, que a quizer dar, aggravando-se per tal petição dos Corregedores da Corte, e Julgadores da Cidade de Lisboa, ou dos lugares dentro de cinco legoas della, a dé ao Regedor, ou aos Porteiros da Relação, para que lha dém na mesa, e elle a veja com os Desembargadores dos Aggravos. E os ditos Porteiros, quando taes petições lhes forem dadas, as tomem, e com diligencia as appresentem ao Regedor, sem por isso levarem cousa alguma. E as petições, que se despacharem, per que mandem levar os autos á Relação, que forem sem sinal do Regedor, havemos por bem, que não valham, nem se faca obra alguma pelo tal desembargo: e o Scrivão, que as ajuntar ao feito, seja suspenso do Officio per seis mezes. E posto que o Regedor seja em opinião, que os autos não venham á Relação, se os Desembargadores dos Aggravos fôrem em mais vozes que venham, porá seu sinal na dita petição. E se no mandar ajuntar estas petições houver desvairo entre os Desembargadores, de maneira que tres, ou mais votem, todos assinarão no despacho.` },
        { id: 'of1-ti-19', number: '19', text: `E para o Regedor melhor ordem ter no despacho das petições, ordenará que sempre na Relação sté hum sacco de dous repartimentos. E em hum delles fará metter as petições despachadas, e em outro as que o não forem: de modo, que, quando se acabar a Relação em cada hum dia, fiquem todas as petições recolhidas no dito sacco. E as despachadas tirará o Porteiro, e não as dará da sua mão ás partes, mas as levará a cada huma audiencia dos aggravos, para o Desembargador, que a fizer, as mandar entregar ás partes, ou á seus procuradores. E não stando presentes, as torne o Porteiro a recolher e metter no dito sacco, donde as tirou, para as levar á outra audiencia seguinte com as mais, que forem despachadas.` },
        { id: 'of1-ti-20', number: '20', text: `Item o Regedor terá cuidado de fazer despachar nos derradeiros dias antes do spaço todos os feitos, que stiverem em Relação, que per petição junta aos autos se mandassem a ella vir: em modo, que nenhum delles fique no spaço das ferias por despachar.` },
        { id: 'of1-ti-21', number: '21', text: `E no mesmo fim de cada anno mandará fazer hum rol a cada hum dos Scrivães de todos os feitos, que na Casa da Supplicação no tal anno se despacharam finalmente, e de quantos lhe ficaram por despachar, para pelo dito rol sabermos os feitos, que cada hum Desembargador despachou, e os que ficam por despachar, e lhes mandarmos dar despacho no anno seguinte.` },
        { id: 'of1-ti-22', number: '22', text: `E bem assi, antes que entrem as ferias, elegerá hum Desembargador, que no tempo dellas veja os feitos, e cartorios dos Scrivães do Crime, e faça executar todas as penas e condenações de dinheiro, que naquelle anno se aplicaram para as despesas da Relação, ou para outras obras pias.` },
        { id: 'of1-ti-23', number: '23', text: `E quando fallecer algum Desmbargador, que tiver Officio na dita Casa, o Regedor nol-o fará logo saber, para Nós provermos na propriedade, ou servintia, como fôr mais nosso serviço. E em quanto não provermos, mandamos, que sendo vago o Officio de Chancellcr, o sirva o Desembargador dos Aggravos mais antigo. E sendo o de algum dos Corregedores do Crime da Corte, ou do Civel, o sirva o compa- nheiro, e o mesmo será, fallecendo algum dos Juízes de nossos feitos. E sendo vago o Officio de algum dos Desembargadores dos Aggravos, ou dos Ouvidores do Crime, se distribuirão de novo os feitos pelos outros. E nos mais Officios, que se servem per Desembargadores, o Regedor encommendará a servintia a outros Desembargadores da Casa, que Officios não tenham, até Nós provermos.` },
        { id: 'of1-ti-24', number: '24', text: `E sendo algum Desembargador, que Officio tenha, absente, ou impedido, de maneira que não possa servir, ou desembargar os feitos, que a elle pertencem, ou os que lhes stiverem commettidos; o Regedor porá outro em seu lugar, que os desembargue, segundo pertencia fazer ao tal Desembargador absente, ou impedido, de maneira que por falta dos ditos Desembargadores principaes os feitos não sejam retardados. E tanto que cessar o dito impedimento, ou absencia, o Desembargador recolherá seus feitos no ponto e stado, em que os achar, sem ficar algum feito áquelle, a quem o dito Officio fôr commettido. E fazendo o Regedor commissão, seja sempre à pessoa, que tenha letras e partes para bem servir o tal cargo, que assi lhe fôr commettido; porém não fará a tal commissão à Desembargador, que Officio outro tenha na Casa. E vindo alguma das partes com embargos à alguma sentença interlocutoria, ou definitiva, dada per aquelle, a quem o dito Officio foi commettido, elle conhecerá dos taes embargos, se na casa stiver; e não stando nella, então conhecerá delles o Juiz proprietario do Officio.` },
        { id: 'of1-ti-25', number: '25', text: `E quando algum Officio de Scrivão, Enqueredor, Distribuidor, Contador, Meirinho, Alcaide, ou outro semelhante da Casa da Supplicação, se não servir, polo proprietario ser morto, absente, ou impedido, o Regedor não proverá pessoa alguma da servintia dos taes Officios; e stando Nós na cidade de Lisboa (onde temos ordenado que a Casa sempre resida), nol-o fará saber, para Nós provermos a quem houvermos por bem. E não stando Nós na dita cidade, poderá o Regedor prover na servintia dos ditos Officios per tempo de dous mezes sómente, os quaes acabados, os não reformará: e as pessoas, a que assi prover, serão das que já tem semelhantes Officios, e outras não. Porém nos Officios de Meirinhos, Alcaides, e seus Scrivães poderá prover as pessoas, que lhe parecer, que melhor podem servir, não passando o dito tempo de dous mezes.` },
        { id: 'of1-ti-26', number: '26', text: `E poderá dar os Officios dos Solicitadores, Caminheiros e Pregoeiros da Casa da Supplicação às pessoas, que para ello lhe parecerem pertencentes, e lhes passará suas cartas.` },
        { id: 'of1-ti-27', number: '27', text: `E se algum Desembargador, ou Official tiver alguma tal necessidade, por que lhe convenha deixar de servir na Relação algum tempo, o Regedor lhe poderá dar lugar e licença per alguns dias, com tanto que não passem de vinte em partes, ou juntamente per todo o anno. E havendo causa para lhe serem dados mais que os ditos vinte dias, será per nossa special Provisão. E quanto à licença, que pode dar aos Scrivães da Corte, guardará o que he conteúdo no Titulo: Dos Scrivães dante os Desembargadores do Paço.` },
        { id: 'of1-ti-28', number: '28', text: `As audiencias dos aggravos e appellações, e Juizo da Chancellaria se farão às terças feiras, quintas e sabbados de cada semana. E as do Juizo dos feitos da Coroa e Fazenda, e Ouvidores do Crime, se farão às segundas, quartas e sextas. E quando parecesse ao Regedor, que as audiencias se deviam fazer em outros dias, por taes necessidades, ou casos, que sobreviessem, ordenal-o-ha, como fôr mais nosso serviço, e bom despacho dos feitos e das partes, em maneira que os feitos se não retardem, antes sejam com mais brevidade despachados, porque este he o mais principal respeito, que se deve ter.` },
        { id: 'of1-ti-29', number: '29', text: `O Regedor se informará cada mez, se as audiencias da Casa são bem feitas, e se os Scrivães de cada huma audiencia vão continuadamente primeiro que o Desembargador, e se tomam os termos nas audiencias, e os screvem logo nellas em seus livros e cadernos, que para isso terão. E assi, se o Meirinho das cadêas vai às audiencias, como he obrigado; ou quando he occupado, se manda lá os homens, que são ordenados. E achando que os Desem- bargadores, que fazem as audiencias, não olham por isso, os amoeste que o façam cumprir, castigando os que achar negligentes, como for direito; do que mandamos ao Regedor, que tenha muito cuidado, porque de os Scrivães o não fazerem assi, se retardam os despachos dos feitos.` },
        { id: 'of1-ti-30', number: '30', text: `E o Regedor com os Corregedores do Crime e seus Scrivães, e com os Desembargadores, que lhe parecer, visitará as cadêas huma vez ao menos em cada mez, na derradeira sexta feira, ou sabbado delle, fazendo audiencia geral aos presos, e trabalhando, quanto for possível, por se despacharem as suas causas com justiça e brevidade, principalmente dos que forem presos por casos leves. E a primeira cousa, de que se informarão, será, se se correo a folha, conforme ao que se dirá no Livro quinto, Título: Como se correrá a folha : castigando os que acharem culpados.` },
        { id: 'of1-ti-31', number: '31', text: `E proverá sobre os Scrivães da Casa da Supplicação, se fazem fielmente seus Officios, e se são diligentes no serviço delles, ou de má resposta ás partes, ou scandalosos, ou lhes levam de suas scripturas mais do que lhes he ordenado. E bem assi dos Distribuidores e Solicitadores da Justiça, se cumprem com as obrigações de seus Officios, tirando em cada hum anno sobre isso devassa delles. E assi poderá tirar as testemunhas, que lhe bem parecer, quando alguma parte se lhe queixar de algum Scrivão. E o que achar que fazem mal, fará emendar, em modo que elles satisfaçam com o que devem. E achando alguns comprendidos em erros, por que mereçam castigo nas pessoas ou nos Officios, remetterá as culpas ao Juiz da Chancellaria. E podel-os-ha suspender, quando pela devassa, ou inquirição lhes achar tal culpa, por que com razão o deva fazer. E tanto que forem suspensos, nol-o fará saber, para mandarmos proceder contra elles pela maneira, que nos parecer, não tolhendo porém ao Chanceller da Casa e ao Juiz da Chancellaria poderem entender nos ditos Scrivães, segundo em os Regimentos de seus Officios he declarado. E assi mais conhecerá o Regedor com os Desembargadores, que lhe bem parecer, da culpa do Julgador, ou Scrivão, em cuja mão se perderem os feitos, como se dirá no Título: Dos Scrivães dante os Desembargadores do Paço e dos Agravos.` },
        { id: 'of1-ti-32', number: '32', text: `E tirará cada anno devassa dos Advogados, que são negligentes e faltam nas Audiencias, e dos que retardam os feitos, e dos Juizes, que não dão á execução a Ordenação, que manda, que os Advogados sejam condenados em dez cruzados, não dando os feitos nos termos, que lhes for mandado. E assi tirará devassa de todos os mais Officiaes da Casa, para se saber como cada hum cumpre com sua obrigação.` },
        { id: 'of1-ti-33', number: '33', text: `Trabalhará de saber, como o Meirinho da Corte, e o das cadêas servem seus Officios, e se nelles satisfazem com as cousas, que são obrigados, e se trazem os homens, que lhes são ordenados, e se são taes, como cumpre para as cousas da justiça. E achando que o Meirinho da Corte faz o que não deve em seu Officio, amoestal-o-ha; e sendo suas culpas taes, por que se deva proceder contra elle, mandalo-ha fazer, segundo ellas merecerem. E se achar que os homens, que tem, não são os que devem, e de que não houver boa informação, mandar-lhos-ha despedir, e tomar outros, que bem sirvam. E quanto ao Meirinho das cadêas, se achar que faz o que não deve, e for comprendido em erros, por que lhe pareça razão suspendel-o do Officio, podel-o-ha fazer, e mandará proceder contra elle, como lhe parecer justiça, e nol-o fará saber, para provermos, como for nosso serviço. E acerca dos homens guardará o que dito he nos do Meirinho da Corte.` },
        { id: 'of1-ti-34', number: '34', text: `Item, proverá muito a miudo sobre o Carcereiro da Corte, sabendo se serve bem seu Officio, ou faz nelle o que não deve, mandando tirar sobre isso devassa: e trabalhará que por descuido, ou negligencia não possa fazer o que não deve. E poderá castigar o Pregoeiro da Corte, se não fizer seu Officio, como he obrigado.` },
        { id: 'of1-ti-35', number: '35', text: `E para que os feitos crimes se despachem mais inteiramente, o Regedor declarará per sua letra os nomes dos Ouvidores, que hão de conhecer delles. Os quaes o Distribuidor distribuirá em numero igual, sem fazer outra alguma declaração.` },
        { id: 'of1-ti-36', number: '36', text: `E quando alguma parte per informação se aggravar de algum Official da Justiça, e no aggravo apontar cousa, que o infame, o Regedor em Relação com acordo dos Desembargadores conheça delle. E se acharem que a infamia não he verdadeira, a farão emendar ao que a poz, per prisão, e per pena corporal, ou pecuniaria, ou per reprehensão de palavra, segundo a qualidade do caso e das pessoas. E achando que o Official foi infamado com razão, o Regedor o deve reprehender publicamente perante os outros Officiaes da Relação; e se merecer mór pena que reprehensão, com acordo dos Desembargadores lhe faça todo emendar, e castigar com a pena, que virem que merece, conforme a qualidade da culpa.` },
        { id: 'of1-ti-37', number: '37', text: `Ao Regedor pertence prover e conservar os stilos e bons costumes ácerca da ordem dos feitos, que sempre se costumaram e guardaram na dita Casa. E não consentirá que Desembargador algum entre, nem stê na Relação com spada, punhal, adaga, ou outra qualquer arma.` },
        { id: 'of1-ti-38', number: '38', text: `E bem assi lhe pertence procurar honra e mercê aos Desembargadores e outros Officiaes da Justiça da Casa, sobre que tem o Regimento, e fazer-lhes guardar seus privilegios.` },
        { id: 'of1-ti-39', number: '39', text: `E se alguns Senhores de terras, ou pessoas, que tem jurisdições, usarem de mais jurisdição, que a que pelas doacões das ditas terras lhes he dada, o Regedor lho não consinta, e proceda contra elles, como per direito deve fazer. E olhe por isto, como por cousa mais principal, e as mais vezes que lhe fôr possível, para se prover, como fôr nosso serviço. E sendo as pessoas, que isto fizerem, de qualidade que nol-o deva fazer saber, o dirá a Nós, ou nol-o scre-verá, não stando a Casa, onde Nós stivermos. O que tudo de novo lhe tornamos a encommendar e mandar.` },
        { id: 'of1-ti-40', number: '40', text: `Item ao Regedor pertence mandar fazer os pagamentos aos Desembargadores aos quarteis, per rol per elle assinado. E no mantimento delles se não fará embargo a requerimento de credor algum, senão per mandado do Regedor; e o thesoureiro, que o houver de pagar, não guardará algum outro embargo feito no dito mantimento; o qual lhe não mandará o Regedor embargar por divida alguma, senão quando achar que o Desembargador fez em seu Officio cousa, por que lhe deva ser embargado.` },
        { id: 'of1-ti-41', number: '41', text: `E per seus Alvarás mandará pagar ao Scrivão de nossos feitos, Carcereiros, Guardas da cadeia, Ministros da Justiça, Porteiros, Caminheiros da Relação, Corredor das folhas, Solicitador da Justiça, e quaesquer outros Officiaes da Casa, que tiverem mantimento, ou ordenado. E quando mandar pagar aos Caminheiros, Corredores das folhas, e Solicitador, o fará com certidão do Promotor da Justiça, de como tem servido como devem, e sem ella não. E bem assi mandará pagar do dinheiro das despesas da Relação ao Capellão della. Porém a nenhum Desembargador, nem Official mandará pagar o tempo, que não servio, salvo stando doente na Corte, ou indo per nossa licença, ou sua fóra.` },
        { id: 'of1-ti-42', number: '42', text: `Item, mandará pagar das despesas da Relação ás testemunhas, que por bem de justiça forem mandadas vir à Corte testemunhar. As quaes nunca mandarão vir para se pagarem das despesas da Rela- ção, senão per mandado do Regedor, que o mandará com acordo da Mesa grande, ou quando forem cinco Desembargadores Juizes da causa, sobre que as mandam vir, todos conformes, como se dirá no Titulo: Dos Ouvidores do Crime da Casa da Supplicação.` },
        { id: 'of1-ti-43', number: '43', text: `E ordenará hum Recebedor, que tenha carrego de receber o dinheiro, que se applicar ás despesas da Relação, e hum Scrivão da sua receita e despesa, e per Alvarás per elle assinado se farão as despesas delle, e se levarão em conta ao Recebedor. E as contas das despesas tomará elle, ou quem elle ordenar. E mandará fazer a quitação da conta, e com sua vista será assinada per Nós.` },
        { id: 'of1-ti-44', number: '44', text: `E mandamos que na Relação haja hum livro assinado e numerado per hum Desembargador, que o Regedor ordenar, que o mesmo Regedor terá fechado de sua mão; no qual todos os Tabelliães e Scrivães das Cidades, Villas, Concelhos e Lugares do districto da Casa da Supplicação, quando tirarem as Cartas de seus Officios, farão os sinaes publicos, de que houveram de usar, e hum termo de sua letra, para na Relação, quando cumprir a bem de justiça, se poderem ver e cotejar os ditos sinaes e letra. E outro tal livro haverá na Casa do Porto, para os Tabelliães e Scrivães dos Lugares e Concelhos do seu districto.` },
        { id: 'of1-ti-45', number: '45', text: `Entre as cousas principaes do Officio de Regedor he, com cuidado e vigilancia saber como os Desembargadores e Officiaes, que para administração da justiça são deputados, vivem e usam de seus Officios, convem a saber, se são negligentes e remissos em seus despachos, ou se são scandalosos ás partes, ou se ha nelles outros defeitos taes, por que seus Officios não sejam servidos, como o devam ser. E quando assim o achar per informação ou fama, que disso haja, chamará o Desembargador, ou Official, que nos ditos defeitos, ou em cada hum delles fôr comprehendido, ou infamado, e apartadamente o amoeste que se emende, e considere como por respeito do Officio, que de Nós tem, he honrado e stimado entre os bons, e recebe de Nós mercê, e com outras mais palavras de amoestação, que segundo a qualidade da pessoa é do caso lhe parecer. E não se emendando pela primeira vez, dir-lho-ha a segunda em presença de outros Officiaes de semelhante Officio, para que a vergonha o obrigue a emendar-se. E quando dahi em diante se não achar emendado, e continuar em seu máo costume, o Regedor nol-o fará saber, para Nós com seu conselho lhe darmos o castigo, que por sua culpa merecer. Porém, sendo o Regedor informado per certa informação, ou per fama publica, que o Desembargador, ou Official recebeo alguma dadiva, ou fez algum erro em seu Officio, nol-o fará saber logo, sem lhe fazer amoestação, para, sabida a verdade, lhe darmos a pena, que por tão graves casos merecer. E os que achar, que vivem bem, e fazem seus Officios como devem, louval-os-ha entre os outros, e nol-o fará saber, para receber de Nós a honra, favor e mercê, que merecer, para que a honra e mercê, que os taes de Nós receberem, e o castigo, que dermos aos que taes não forem, por suas culpas, seja a outros exemplo, para se guardarem de máos costumes, e viverem como devem.` },
        { id: 'of1-ti-46', number: '46', text: `No derradeiro dia de Agosto em cada hum anno mandará fixar na porta da Relação Alvará, per que notifique aos Desembargadores, que he concedido spaço pelos dous mezes seguintes, e que ao terceiro dia de Novembro venham continuar seus Officios á dita Casa na cidade de Lisboa, onde reside. E mandará aos Scrivães e outros Officiaes della, que ao dito termo sejam presentes. E naquelle tempo do spaço levantará as residencias aos que andarem per carta de seguro, ou sobre alvará de fiança. E os que andarem presos sobre suas homenagens, ficarão na dita cidade. E assi a huns, como a outros, mandará, que pareçam na Relação ao dito termo.` },
        { id: 'of1-ti-47', number: '47', text: `E quando por algum caso mandarmos, que a Casa da Supplicação se mude da ci- dade de Lisboa para alguma outra parte, mandará aposentar os Officiaes da Casa per hum Scrivão, que irá diante fazer o aposento, como o faz o nosso Aposentador. E se alguma pessoa se aggravar delle, o Regedor conhecerá do aggravo.` },
        { id: 'of1-ti-48', number: '4', text: `E quando o Regedor fôr absente, ficará em seu lugar o Chanceller da Casa. E não stando ahi o Chanceller, o Regedor deixará em seu lugar o Desembargador dos Aggravos, que fôr mais antigo, ou nol-o fará saber, para provermos nisso, como fôr nosso serviço.` },
      ],
    },
    {
      id: 'titulo-ii',
      title: `II. Do Chanceller Mór`,
      type: 'articles',
      articles: [
        { id: 'of1-tii-preambulo', number: 'Preâmbulo', text: `O Officio de Chanceller Mór he de grande confiança, e de que muita parte da Justiça pende.

Por tanto devemos para elle escolher pessoa, que seja de boa linhagem e de bom entendimento, virtuoso, letrado e de bom Depois da creação da nova Casa da Supplicação do Brasil tomárão-se diferentes providencias sobre taes substituições e impedimentos.

Era um dos primeiros empregos da antiga Monarchia Portugueza.

As outras attribuições ficarão a cargo das differentes Secretarias de Estado, e as receitas de certos impostos cobradas pelo Thesouro Nacional.

acolhimento ás partes, para que os que com elle tiverem que negociar, sem alguma difficuldade o possam fazer: e de tal entendimento e memoria, que saiba conhecer os erros e faltas das scripturas, que per elle hão de passar, e que se lembre, que não sejam contrarias humas a outras; e de tão bons costumes e auctoridade, que seja merecedor do lugar, em que per Nós he posto.

E deve amar a Nós e a nosso Stado, de maneira que possa e saiba servir o dito Officio, como he obrigado, e como cumpre a nosso serviço, e a bem de nossos vassallos e povo.` },
        { id: 'of1-tii-1', number: '1', text: `E tanto que o dito Officio fôr provido, antes de o servir, nem delle em cousa alguma usar, o Presidente da Mesa do despacho dos Desembargadores do Paço lhe tomará juramento na dita Mesa diante os Desembargadores; e em ausencia do Presidente lhe tomará o juramento o Desembargador mais antigo da dita Mesa.` },
        { id: 'of1-tii-2', number: '2', text: `Ao Chanceller Mór pertence ver com boa diligencia todas as cousas, que per qualquer maneira per Nós, ou pelos Desembargadores do Paço, Védores da Fazenda, Desembargadores della, Provedor Mór das obras e terças, Anadeis Móres dos Espingardeiros e Bésteiros, Monteiro Mór, Physico Mór, Cirurgião Mór forem passadas e assinadas, ou per quaesquer outros Officiaes da Corte, cujos despachos houverem de passar pela Chancellaria, tirando as cartas e sentenças, que forem passadas na Casa da Supplicação, e pelos Desembargadores della. E vendo o Chanceller Mór pela decisão da carta ou sentença, que ha de sellar, que vai expressamente contra as Ordenações, ou Direito, sendo o erro expresso na dita carta, ou sentença, per onde conste ser nenhuma, não a sellará, mas ponha-lhe sua glosa, quando as cartas, ou sentenças forem assinadas pelos ditos Officiaes. E stando a Corte fóra da cidade de Lisboa, o Chanceller Mór passará as cartas e sentenças dos feitos e causas, que o Corregedor da Corte despachar, postoque a Corte sté dentro das cinco legoas donde a Casa da Supplicação stá. E indo o Corregedor do lugar, donde stivermos, á Casa da Supplicação despachar algum feito, passará a carta, ou sentença pelo Chanceller da Casa.` },
        { id: 'of1-tii-3', number: '3', text: `E quando o Chanceller Mór tiver dúvida a haver de passar pela Chancellaria algumas Provisões assinadas per Nós de cousas despachadas pelos Desembargadores do Paço, ou per outros Officiaes da Corte, as praticará com os Desembargadores do Paço, para com elles ver se passarão. E assentando, que não devem passar, as rompera logo, pondo nas costas dellas, como foram rotas, por se determinar, que não haviam de passar. E quando lhes parecer, que devem passar com alguma declaração, ou limitação, pôr-se-ha o despacho conforme ao que assentarem, e disso se fará Provisão para se assinar per Nós. E quando o Chanceller Mór tiver dúvida em haver de passar pela Chancellaria algumas Provisões feitas em nosso nome, e assinadas pelos ditos Desembargadores do Paço, ou outros Officiaes da Corte, de cousas, que elles podem assinar, praticará as taes dúvidas com os ditos Desembargadores, e se cumprirá o que elles determinarem, assi ácerca de haverem de passar pela Chancellaria, ou não, como em se fazerem em outra fórma com alguma limitação, ou declaração. E para se isto assi cumprir, irá em cada semana hum dia à Mesa do despacho dos ditos Desembargadores do Paço com as dúvidas; e quando assi fór, não se tratarão outros negocios, até se tomar determinação nellas. No despacho das quaes serão todos os Desembargadores, que se acharem na Mesa com o dito Chanceller Mór, e não será presente nenhum Scrivão da Camera, salvo sendo chamado. E sendo as glosas, ou dúvidas postas ás Cartas, ou Provisões, que passarem os Védores da Fazenda, ou outros Officiaes dellas, parecendo aos ditos Desembargadores do Paço, que deve ser ouvido o Procurador de nossa Fazenda, lhe mandarão recado, para se achar presente o dia, em que o Chanceller Mór as levar á Mesa dos ditos Desembargadores do Paço.` },
        { id: 'of1-tii-4', number: '4', text: `Achando o Chanceller Mór algumas Cartas ou Provisões de graça, contra nossos direitos, ou contra o povo, ou Clerezia, ou outra alguma pessoa, que lhe tolha, ou faça perder seu direito, não as assinará, nem mandará sellar, até que falle comnosco. E nas Cartas, em que dermos alguma cousa do nosso, não as sellará, sem primeiro serem registradas na Fazenda pelo Scrivão, que para isso fôr ordenado, e as Nós desembargarmos pela emmenta, sendo taes, que pela dita emmenta devam passar. E as Cartas, que per ella passarem, não as assinará, até ver a dita emmenta, a qual o Scrivão da Chancellaria lhe mandará mostrar. E o mesmo fará nas Cartas, que passarem per quaesquer Officiaes, que houverem de ir á emmenta. E as Cartas, que passarem pelos Desembargadores do Paço, que houverem de levar nosso passe, as não passará, sem ver o dito nosso passe.` },
        { id: 'of1-tii-5', number: '5', text: `O Chanceller Mór mandará aos Scrivães, que façam as Cartas e sentenças bem scriptas, e por sua mingua não sejam glosadas, nem as partes por isso detidas. E sendo alguma glosada de modo, que se deva fazer outra de novo, se o erro fôr por culpa do Scrivão, o Chanceller Mór lhe fará logo tornar à graça. E se fôr por culpa dos Desembargadores, que a passaram, elles pagarão ao Scrivão, e o Chanceller Mór determinará por cuja culpa se glosou.` },
        { id: 'of1-tii-6', number: '6', text: `Tanto que as Cartas forem vistas pelo Chanceller Mór, e achar que nellas não ha dúvida, para deixarem de passar, porá nellas seu sinal costumado, segundo os sellos forem, e as mandará sellar perante si ao Porteiro da Chancellaria, e metter em um sacco, que o dito Porteiro cerrará e sellará, e o levará direitamente á Casa da Chancellaria sem detença alguma, para se darem ás partes perante o Recebedor e Scrivão della.` },
        { id: 'of1-tii-7', number: '7', text: `O Chanceller Mór conhecerá de todas as suspeições, que forem postas aos Desembargadores do Paço, Védores da Fazenda, e Desembargadores della, e a todos os mais Officiaes acima nomeados. E commeterá os feitos, em que houver os ditos Desembargadores e Officiaes por suspeitos, ou se elles lançarem, depois de ser a suspeição procedida per elle; e fará as commissões a outros Juizes, que lhe bem parecer: salvo nas suspeições, que julgar, dos Védores da Fazenda, porque depois de julgados por suspeitos, não commeterá os feitos a outrem em seu lugar, mas as partes neste caso, ou lançando-se cada hum dos ditos Officiaes por suspeito, antes da suspeição procedida, nol-o requererão, para nomearmos outro Official, que do negocio conheça.` },
        { id: 'of1-tii-8', number: '8', text: `E poderá julgar as suspeições postas a cada huma das pessoas acima ditas, postoque lhe seja suspeito, não se tratando nas suspeições da honra, ou interesse consideravel da tal pessoa recusada: e tratando-se de qualquer das ditas cousas, não conhecerá da suspeição, e será dado outrem em seu lugar. E havendo dúvida, se se trata de alguma das ditas cousas, a pessoa, a que fôr posta a suspeição, ao tempo de depôr a ella poderá allegar as causas, por que o dito Chanceller Mór não deve conhecer della, com as quaes a suspeição irá logo aos Desembargadores do Paço, que determinarão, se deve conhecer della, ou não. E entretanto não irá com a suspeição por diante.` },
        { id: 'of1-tii-9', number: '9', text: `Ao Chanceller Mór pertence saber, se alguns Scrivães, ou Tabelliães da Corte, ou do lugar, onde ella stiver, levam mais de suas scripturas, ou buscas, que o conteúdo em seus Regimentos e nossas Ordenações, e lhes fará tornar o que mais levaram. E se por isso merecerem outra mais pena, os remeteril ao Corregedor do Crime da Corte, que conhecerá disso, e os despachará em Relação. E isto se não entenderá nos Officiaes das Casas da Supplicação, ou do Porto, postoque a Corte stê no lugar, onde cada huma das ditas Casas ha de residir, porque então o conhecimento pertence aos Chancereis das ditas Casas.` },
        { id: 'of1-tii-10', number: '10', text: `Item o Chanceller Mór ha de publicar as Leis e Ordenações feitas per Nós, as quaes publicará per si mesmo na Chancellaria da Corte no dia da dada das Cartas, e mandará o traslado dellas sob seu sinal e nosso sello aos Corregedores das Comarcas. E tanto que qualquer Lei, ou Ordenação for publicada na Chancellaria, e passarem tres mezes depois da publicação, mandamos, que logo haja effeito e vigor, e se guarde em tudo, postoque não seja publicada nas Comarcas, nem em outra alguma parte, aindaque nas ditas Leis e Ordenações se diga, que mandamos, que se publiquem nas Comarcas; por quanto as ditas palavras são postas para se melhor saberem, mas não para ser necessario, e deixarem de ter força, como são publicadas na nossa Chancellaria, passados os ditos tres mezes. Porém em nossa Corte haverão effeito e vigor, como passarem oito dias depois da publicação.` },
        { id: 'of1-tii-11', number: '11', text: `O Chanceller Mór determinará quaesquer dúvidas, que sobrevierem sobre o que se deve pagar da Chancellaria de quaesquer Cartas, ou Alvarás, que per ella passarem, com os Desembargadores, que Nós para isso ordenarmos, sem apellação, nem aggravo. E todos os outros casos, de que o conhecimento lhe pertence, despachará per si só. E cada huma das partes, que delle se sentir aggravada, poderá aggravar per petição á Mesa dos Desembargadores do Paço.` },
        { id: 'of1-tii-12', number: '12', text: `O Chanceller Mór dará juramento a todos Officiaes e pessoas abaixo declaradas, quando Nós os provermos novamente de Officios, e passarem suas Cartas pela Chancellaria: convém a saber, ao Condestabre, Regedor da Casa da Supplicação, Governador da Casa do Porto, Védores da Fazenda, Scrivão da Puridade, Almirantes, Marichal, Capitães dos lugares de Africa e das Ilhas, e a todos os Officiaes Móres de nossa Casa e do Reino, Fronteiros Móres, Desembargadores da Casa da Supplicação e do Porto, e aos Corregedores das Comarcas, Ouvidores, Provedores e Juizes de fóra. E quanto he ao Regedor e Governador, e Védores da Fazenda, e Desembargadores, e Corregedores das Comarcas, Ouvidores e Provedores, e Juizes de fóra, dará o juramento na fórma conteúda no livro dos juramentos da Casa da Supplicação. E ao Condestabre, e a todos os outros Officiaes acima nomeados dará juramento, que bem e fielmente sirvam seus Officios, segundo per seus Regimentos lhes he ordenado, e guardem inteiramente nosso serviço, e direito e justiça ás partes.` },
        { id: 'of1-tii-13', number: '13', text: `E assi dará o dito Chanceller Mór juramento a todos os que Nós fizermos de nosso Conselho, o qual lhes será dado ao tempo, que tirarem suas Cartas da Chancellaria, os quaes jurarão em esta fórma: Que bem e fielmente nos darão seu conselho, quando per Nós lhes fôr requerido. E que inteiramente guardarão nossos segredos sem os descobrirem em tempo algum, senão quando lhes fôr mandado per Nós, ou elles forem publicados. E assi qualquer cousa de nosso serviço, que toque a nossa pessoa e stado, elles nol-o farão saber o mais prestes que poderem.` },
        { id: 'of1-tii-14', number: '14', text: `E quando a cada huma das ditas pessoas der o juramento, porá nas costas da Carta sua fé per seu sinal, como lhes deo o dito juramento. E a Carta, que passár, sem levar a dita fé, será nenhuma, e não se cumprirá, e ficará a Nós prover do tal Officio, como fór nossa mercê.` },
        { id: 'of1-tii-15', number: '15', text: `E os Corregedores, Ouvidores, Provedores e Juizes de fóra, que servirem seus Officios, antes de lhes ser dado o dito juramento, serão obrigados ás partes a toda a perda e dano, que por isso se lhes causar. E todo per elles feito será nenhum, e de nenhum vigor, como de não Juizes, nem Officiaes, postoque nossas Cartas tenham.` },
        { id: 'of1-tii-16', number: '16', text: `E não passará Cartas, ou Alvarás alguns, que não levarem postas as pagas do que os Scrivaes, que as fizeram, levaram de feito dellas.` },
        { id: 'of1-tii-17', number: '17', text: `E quando a nossa Corte não stiver na cidade de Lisboa, onde a Casa da Supplicação reside, mandará o Chanceller Mór contar os feitos dos presos pobres, que na Corte se tratarem, e cumprirá em tudo o que se contém na Ordenação Titulo: Dos Scriváes dante os Desembargadores do Paço, no §: E quanto ao pagamento dos feitos. E sendo o Contador das custas suspeito, ou impedido, que não possa fazer a dita conta, ou depois de feita a dita conta, as partes allegarem erros sobre ella, o Corregedor da Corte, que comnosco andar, commetterá as taes contas a huma pessoa, que bem e sem suspeita a possa fazer. E no caso dos erros, o dito Corregedor conhecerá delles, e os determinará, como lhe bem parecer. E quando alguma parte se aggravar de sua determinação, Nós proveremos quem disso haja de conhecer.` },
        { id: 'of1-tii-18', number: '18', text: `Poderá o Chanceller Mór mandar citar em todo caso, que a seu Officio pertencer, até cinco legoas, onde a Corte stiver, per seu Alvará, ou Porteiro. E nos casos, em que por bem de seu Officio póde mandar citar alguma pessoa, poderá dar licença á parte, ou á qualquer outra pessoa em seu nome, para poder citar perante huma testemunha ao menos.` },
        { id: 'of1-tii-19', number: '19', text: `E não sellará as Cartas, que per Nós forem assinadas, em que dermos licença a algumas Igrejas, ou Ordens, para comprarem bens de raiz até certa quantia, sem nas ditas Cartas ser posta clausula, que lhes damos licença, que possam comprar quaesquer bens de raiz até a dita quantia, e mais não, com condição que os ditos bens não sejam em nossos Reguengos, nem em terras Jugadeiras, nem bens, que a Nós sejam obrigados fazer algum fóro, ou tributo. E que os nossos Contadores e Almoxarifes façam registrar a dita Carta de licença nos livros dos proprios. E ás compras, que por vigor della se fizerem, sejam presentes os ditos Almoxarifes. As quaes Cartas farão registrar no dito livro, em maneira que em todo tempo se possa saber, como as taes compras não passaram da dita quantia per Nós outorgada. E sendo caso, que sem as ditas clausulas passem, havemos por bem que sejam nenhumas e de nenhum vigor.` },
        { id: 'of1-tii-20', number: '20', text: `E não passará pela Chancellaria Carta alguma de privilegio de Bésteiro, passada pelo Anadel Mór, em que se contenha, que não pague Jugada de pão. E quando lhe fór ter á mão a tal Carta, fará tirar a dita clausula.` },
        { id: 'of1-tii-21', number: '21', text: `Por se evitarem alguns inconvenientes de o Chanceller Mór passar pela Chancellaria as sentenças, que em alguns casos der, e Cartas, que per si passar, nos casos, em que o póde fazer, ou nos feitos, em que fór autor, ou reo, mandamos que o Desembargador do Paço mais antigo no Officio passe as ditas Cartas e sentenças. E tendo o dito Desembargador do Paço alguma duvida, ou glosa, as determinará na Mesa, como acima fica dito que o ha de fazer o Chanceller Mór.` },
        { id: 'of1-tii-22', number: '22', text: `E quando o Chanceller Mór fór impedido, ou tiver necessidade de se absentar da Corte, nol-o fará saber, para nomearmos quem por elle sirva, em quanto durar seu impedimento, ou absencia.` },
      ],
    },
    {
      id: 'titulo-iii',
      title: `III. Dos Desembargadores do Paço`,
      type: 'articles',
      articles: [
        { id: 'of1-tiii-preambulo', number: 'Preâmbulo', text: `Aos nossos Desembargadores do Paço pertence despa,char as petições de graça, que nos fôr pedida, em causa, que a Justiça possa tocar, assi como Cartas de privilégios e liberdades às pessoas, a que per nossas Ordenações forem outorgadas, que não sejam nem toquem à direitos, rendas e tributos nossos.` },
        { id: 'of1-tiii-1', number: '1', text: `Item, Cartas de legitimações, confirmações de perfilhamentos, e de doações, que algumas pessoas fizerem a outras.` },
        { id: 'of1-tiii-2', number: '2', text: `Item, Cartas de restituição de fama, e de qualquer outra habilitação.` },
        { id: 'of1-tiii-3', number: '3', text: `Item, Cartas de fintas, e Cartas de Officios de sesmarias nos lugares, em que a Nós pertence a dada, e não pertencer a outros nossos Officiaes per seus Regimentos.` },
        { id: 'of1-tiii-4', number: '4', text: `E bem assi Cartas de confirmações das eleições dos Juizes Ordinários, ou dos Orfãos, quando a elles vierem.` },
        { id: 'of1-tiii-5', number: '5', text: `Item, Cartas de inimizade nos casos, em que por stilo de nossa Corte se devem dar. As quaes não darão contra Corregedores, Ouvidores, Juizes, nem outros Julgadores.` },
        { id: 'of1-tiii-6', number: '6', text: `Outrosi darão Cartas tuitivas, e Cartas de manterem em posse os appellantes, ou tornarem a ella, se depois da appellação forem esbulhados. E Cartas restitutorias de quaesquer possuintes e esbulhados, postoque appellantes não sejam.` },
        { id: 'of1-tiii-7', number: '7', text: `E Cartas de emancipação, e supplemento de idade. As quaes não passarão per outros Desembargadores, nem Officiaes de Justiça, nem per outras pessoas, de qualquer qualidade que sejão, que qualquer jurisdição tiverem, nem per seus Ouvidores. E passando-se per qualquer pessoa, que não fôr pelos ditos Desembargadores do Paço, seja nenhuma, e de nenhum effeito; e o que a passar, perca o Officio, que tiver, e nunca mais o haja; e mais pague cincoenta cruzados, ametade para quem o accusar, e a outra para os Cativos: e se for Senhor de terras, perca a jurisdição, que tiver.` },
        { id: 'of1-tiii-8', number: '8', text: `E passarão outrosi, com nosso passe, as Cartas dos perdões, que se dão aos homiziados e aos condenados. E no receber das petições dos ditos perdões terão a maneira seguinte.` },
        { id: 'of1-tiii-9', number: '9', text: `Em todo o caso, em que houver parte, não tomarão petição, sem se offerecer com ella perdão de todas as partes, a que tocar, ou se forem dos casos conteúdos no (Liv. 5) Titulo: Como se perdoará aos malfeitores, que derem outros á prisão. E postoque as partes digam, que não querem accusar, ou que deixam o feito á Justiça, e offereçam disso certidão, não lhes serão recebidas as petições, nem as taes certidões, havidas por perdão; mas será necessario trazerem expresso perdão das partes.` },
        { id: 'of1-tiii-10', number: '10', text: `E quando algum pedir perdão de morte em rixa, passados oito annos, facam vir as devassas: e tendo perdão das partes, provando-se a morte em rixa, seja lhe dado perdão, com tanto que vá servir aos lugares de Africa cinco annos cumpridos qual o Rey fazendo uso do seu direito de proteger os seus subditos, os defendia das violencias ecclesiasticas, e lhes mantinha o uso e posse dos seus bens.

Confronte-se este paragrapho com o 116 do Regimento do Desembargo do Paço, e a Ord. do Liv. 2 t. 10, e 1. 3 t. 85 § 1.

Confronte-se este paragrapho com o § 117 do t. 62 deste liv. § 3 do t. 9, e t. 42 do liv. 3.

As cartas tuitivas erão um meio extraordinario, pelo continuadamente, sem lhe ser dada licença para sair do lugar para outras partes. E não lhe será mudado este degredo para outro Couto, nem diminuido o tempo delle. E se as mortes forem por cajão, mandarão trazer as inquirições, que sobre ellas forem tiradas; e tendo perdão das partes, sejam vistas e examinadas, e segundo as provas dellas, e culpas dos matadores, assi lhe sejam dados os perdões, ou livremente, ou com alguma pena, segundo o caso merecer.` },
        { id: 'of1-tiii-11', number: '11', text: `E porque nas inquirições devassas, que assi são tiradas, ás vezes se não prova claramente a culpa porém mostram-se alguns indícios e presunções suffícientes para tormento, ou outros indícios, que não são suffícientes para os culpados serem mettidos a tormento: havemos por bem que em taes casos possam ser perdoados com alguma pena de degredo de certos annos para Africa, ou para o Couto de Castro Marim, segundo forem as culpas; com tanto que sejam as mortes em rixa, e os oito annos sejam passados, e que tenham perdão das partes.` },
        { id: 'of1-tiii-12', number: '12', text: `Na petição de alevantamento de degredo se declarará o tempo, que o condenado tem servido o degredo; e se foi para lugar certo, offereça certidão authentica com o traslado da verba do livro, em que se assentou, quando começou a servir o degredo, e com prova de testemunhas, que per juramento digam, que sabem ter servido na maneira declarada em sua petição. E offerecerá a sentença de sua condenação, da qual se fará menção na Carta de perdão.` },
        { id: 'of1-tiii-13', number: '13', text: `Havemos por bem que quando se moverem algumas duvidas antre os Desembargadores da Casa da Supplicação e os da Casa do Porto sobre feitos, se pertencerem a cada qual das Casas, os Desembargadores do Paço sejam disso juizes. E havida a informação necessaria, nos darão conta, e com nossa auctoridade determinarão em quaes das Casas se devem tratar os taes feitos. E o que ácerca disso per elles fôr determinado, mandamos ao Regedor e Governador o façam inteiramente cumprir e guardar.` },
        { id: 'of1-tiii-14', number: '14', text: `E tomarão conhecimento dos instrumentos de aggravo ou Cartas testemunhaveis, que tirarem algumas pessoas, por se quererem escusar de servir os Officios de Vereadores, e os mais da Governança das cidades e villas. E isto sendo nomeados no Desembargo do Paço para servirem os taes Officios, conforme as pautas, que a elle vem, e os despacharão finalmente, como fôr justiça. E dos ditos instrumentos se não tomará conhecimento em nenhuma das Relações, nem per outro algum Julgador.` },
        { id: 'of1-tiii-15', number: '15', text: `E porque alem das cousas declaradas nesta Ordenação, lhe temos commettido o despacho de outros casos per hum Regimento, que lhes démos, para andar no Desembargo do Paço, mandamos que o cumpram e guardem, como em elle se contém.` },
      ],
    },
    {
      id: 'titulo-iv',
      title: `IV. Do Chanceller da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-tiv-preambulo', number: 'Preâmbulo', text: `O Officio de Chanceller da Casa da Supplicação he o segundo della. E tanto que o Chanceller fôr delle per Nós provido, antes de o servir, o Regedor da dita Casa lhe dará juramento na Mesa grande, perante todos os Desembargadores, que presentes forem.` },
        { id: 'of1-tiv-1', number: '1', text: `Ao dito Chanceller pertence ver com As attribuições dos Chancelleres das Relações do Brasil passárão para os respectivos Presidentes, menos as glosas.

boa diligencia todas as Cartas e sentenças, que passarem pelos Desembargadores da dita Casa, antes que as selle. E vendo pela decisão da Carta, ou sentença, que vai expressamente contra as Ordenações, ou direito, sendo o dito erro expresso, por onde conste pela mesma Carta, ou sentença, se em si nulla, a não sellará, e pòr-lhe-ha sua glosa, e a levará à Relação, e fallará com o Desembargador, ou Desembargadores, que a tal Carta, ou sentença passaram. E se entre o dito Chanceller e Officiaes, que o tal desembargo assinaram, houver sobre a dita glosa differença, determinar-se-ha perante o Regedor com os Desembargadores, que para isso lhes parecerem necessários, e passará como pela maior parte delles fôr determinado. E tanto que o dito Chanceller propozer a glosa, se apartará, como se apartam os Desembargadores, que nas taes sentenças e Cartas foram, e não será presente ao votar sobre ella, para que os Desembargadores, que as houverem de determinar, o façam livremente, como lhes parecer justiça. E isto haverá lugar, assim nas cartas e sentenças, que forem desembargadas em Relação, como nas que per hum, ou dous, ou mais passarem.` },
        { id: 'of1-tiv-2', number: '2', text: `Mandará aos Scrivães, que façam as sentenças e Cartas em maneira, que sejam bem feitas e scriptas, e por sua culpa não sejam glosadas, nem as partes por isso detidas. E sendo alguma sentença, ou Carta glosada justamente, de modo que se deva fazer outra, se o tal erro fòr por culpa do Scrivão, o Chanceller fará logo tornar à parte todo o dinheiro, que por ella recebeo, ou fazer outra de graça. E se fòr por culpa dos Desembargadores, que a passaram, elles a pagarão ao Scrivão, que a fizer. E o Chanceller determinará por cuja culpa se glosou.

As Relações da India ou de Gôa, do Brasil, posteriormente da Bahia, do Rio de Janeiro, Maranhão e Pernambuco tinhão nos Vice-Reys e Capitães-Generaes os seus respectivos Governadores, mas o verdadeiro chefe era o Chanceller.

Em cada um destes Regimentos se achão enumeradas as attribuições de seus respectivos Chancelleres.

Segundo o art. 22 da Disposição Provisoria, já citada, as Relações são presididas por um dos tres Desembargadores mais antigos, nomeado triennalmente pelo Governo.` },
        { id: 'of1-tiv-3', number: '3', text: `E tanto que as Cartas forem vistas pelo Chanceller, e achar que nellas não ha duvida para deixarem de passar, porá nellas seu sinal costumado, segundo os sellos forem, e as mandará perante si sellar ao Porteiro da Chancellaria, e pòr em hum sacco, que o dito Porteiro cerrará e sellará. E assi bem cerrado e sellado o levará logo direitamente e sem detença à Casa da Chancellaria, para se darem as ditas Cartas perante o Recebedor e Scrivão della.` },
        { id: 'of1-tiv-4', number: '4', text: `E conhecerá de todas as suspeições postas aos Desembargadores, e a todos os outros Officiaes da Casa da Supplicação; e commetterá os feitos, em que elle houver por suspeitos os ditos Desembargadores e Officiaes, ou se elles lançarem por suspeitos, depois de ser a suspeição procedida, e farás as commissões a outros Desembargadores, que lhe bem parecer. E isto fará, quando se houver de fazer commissão per bem de suspeição, posta a algum Desembargador, ou a outro Official da Casa. Porém, onde fòr posta suspeição em presença do Regedor a algum Desembargador, que ao despacho do feito stiver em Relação, ou no caso, em que se o Desembargador der por suspeito, antes da suspeição ser procedida, elle não conhecerá disso, nem commetterá, por quanto pertence ao Regedor.` },
        { id: 'of1-tiv-5', number: '5', text: `E sendo o Chanceller suspeito ao Desembargador, ou Official, de cuja suspeição se tratar, se guardará o que dissemos no Titulo 2: Do Chanceller Mór, no § 8: E poderá; e os acompanhados com outro Desembargador, em lugar do dito Chanceller, determinarão se se trata de honra, ou interesse consideravel do tal recusado, para o dito Chanceller haver de conhecer da suspeição, ou se dar outrem em seu lugar. E o Chanceller não stará presente, quando se votar na tal determinação.` },
        { id: 'of1-tiv-6', number: '6', text: `Ao Chanceller pertence saber, se alguns Scrivães da Casa, ou Tabelliães do lugar, onde ella stiver, levam mais de suas scripturas, ou buscas, que o conteido em seus Regimentos, e nossas Ordenações, as quaes fará cumprir e guardar, e lhes fará tornar o que mais levaram; e se por isso merecerem outra mais pena, os remetter à ao Juiz da Chancellaria. Porém, stando Nós em Lisboa, onde a Casa reside, conhecerá sómente do que toca aos Scrivães da dita Casa, para lhes fazer tornar o que mais levaram, e mais não. Porque quando Nós stivermos na dita cidade, o Chanceller Mór proverá sobre os Oficiaes della, como em seu Titulo 2 se contém.` },
        { id: 'of1-tiv-7', number: '7', text: `Item, desembargará em Relação quaesquer dividas, que sobrevierem sobre o que se deve pagar de Chancellaria de quaesquer Cartas, que per ella passarem, segundo he declarado no Titulo 20: Do Scrivão da Chancellaria da Casa da Supplicação.` },
        { id: 'of1-tiv-8', number: '8', text: `Item, stará ao exame dos Procuradores, que houverem de entrar na Casa da Supplicação, e lhes passará suas certidões de como foram examinados, e se achou serem aptos. E os Desembargadores do Paço per ella lhes mandarão fazer suas Cartas, e as assinarão, e serão selladas pelo Chanceller Mór.` },
        { id: 'of1-tiv-9', number: '9', text: `E não passará Cartas algumas, sem levarem postas as pagas do que os Scrivães, que as fizeram, levaram do feitio dellas.` },
        { id: 'of1-tiv-10', number: '10', text: `Item, mandará contar os feitos dos presos pobres da dita Casa da Supplicação, e cumprirá em tudo a Ordenação deste Livro no Titulo 24: Dos Scrivães diante os Desembargadores do Paço, no § 43: E quanto ao pagamento dos feitos.` },
        { id: 'of1-tiv-11', number: '11', text: `E nos casos, em que póde mandar citar per bem de seu Officio, poderá dar licença à parte, ou à qualquer outra pessoa em seu nome, para poder citar perante huma testemunha ao menos.` },
        { id: 'of1-tiv-12', number: '12', text: `E poderá mandar citar em todo o caso, que a seu Officio pertencer, até cinco legoas donde a Casa stiver, per seu Alvará, ou Porteiro.` },
        { id: 'of1-tiv-13', number: '13', text: `Item, o Chanceller despachará em Relação com os Desembargadores, que lhe o Regedor ordenar, as suspeições, de que por bem de seu Regimento lhe pertencer o conhecimento. E quando alguma pessoa se aggravar de algum desembargo, que o dito Chanceller per si só der, e elle stiver na Mesa ao tempo, que se houver de despachar, se apartará para outra parte, em quanto se derem as vozes sobre o dito aggravo.` },
        { id: 'of1-tiv-14', number: '14', text: `E não passará as Cartas testemunhaveis, que se derem de alguns autos, e assi as Cartas, que se fizerem para tirarem inquirições per artigos, sem irem concertadas pelo Scrivão, que as fez, com outro Scrivão, que assinará ao pé da tal Carta, como a concertou.` },
        { id: 'of1-tiv-15', number: '15', text: `E as sentenças, que der, e as Cartas, que per si passar, e as em que fór autor, ou réo, as passará e assinará o Desembargador dos Agravos da dita Casa mais antigo no Officio. E as glosas, que o dito Desembargador pozer, ou dividas, que tiver ás ditas sentenças, ou Cartas, despachará com os mesmos Desembargadores, com que o Chanceller as houvera de despachar.` },
        { id: 'of1-tiv-16', number: '16', text: `E quando o Regedor fôr absente, o Chanceller ficará em seu lugar.` },
        { id: 'of1-tiv-17', number: '17', text: `E sendo o Chanceller impedido, ou tendo necessidade de se absentar da Casa, deixará o Sello a hum dos Desembargadores dos Agravos, com parecer do Regedor. E fallecendo o Chanceller, o Regedor nol-o fará saber, para provermos na propriedade, ou servintia. E em quanto Nós não provermos, servirá o dito Officio o Desembargador dos Aggravos mais antigo, como temos dito no Titulo 1: Do Regedor.` },
      ],
    },
    {
      id: 'titulo-v',
      title: `V. Dos Desembargadores da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-tv-preambulo', number: 'Preâmbulo', text: `Querendo Nós dar ordem, que as causas, que na Casa da Supplicação se tratam, sejam brevemente despachadas, mandamos que na dita Casa haja os Desembargadores seguintes: Hum Chanceller da dita Casa, dez Desembargadores dos Aggravos e Appellações, dous Corregedores do Crime da Corte, dous Corregedores das Causas civeis della, dous Juizes dos Feitos de nossa Coroa e Fazenda, quatro Ouvidores das Appellações de casos crimes, hum Procurador dos Feitos de nossa Coroa, hum Procurador dos Feitos da nossa Fazenda, hum Juiz de Chancellaria, hum Promotor da Justiça, e quinze Desembargadores Extravagantes.` },
        { id: 'of1-tv-1', number: '1', text: `E os Letrados, que tomarmos para a Casa da Supplicação, entrarão primeiro na Casa do Porto, e nella terão servido algum tempo.` },
        { id: 'of1-tv-2', number: '2', text: `E tanto que algum Desembargador for per Nós provido de algum Officio, o servirá per si, como he obrigado, do dia que fôr provido a dez dias primeiros seguintes. E não servindo no dito tempo, o Regedor o não consentirá que vá a rol, para lhe ser pago seu ordenado, e nol-o fará saber, para provermos do tal Officio, como for nossa mercê.` },
        { id: 'of1-tv-3', number: '3', text: `E quando tomarmos algum Letrado para a Casa da Supplicação por Desembargador, antes que feito algum desembargue, o Regedor lhe dará juramento na Mesa grande perante todos os Desembargadores, o qual juramento fará na forma, que stá scripto no livro da Relação. E tanto que o dito juramento tomar, porá seu sinal ao pé do que está scripto. E sem se screverem outros juramentos de novo, assinarão da mesma maneira os Desembargadores, que pelo tempo forem providos.` },
        { id: 'of1-tv-4', number: '4', text: `E mandamos, que todos nossos Desembargadores, que não cumprirem e guardarem nossas Ordenações inteiramente, sendo-lhes allegadas, paguem às partes, em cujo favor forem allegadas, vinte cruzados, e sejam suspensos de seus Officios até nossa mercê, e por esse mesmo feito ficarão suspeitos às ditas partes em os feitos, de que assim forem Juizes. E os desembargos e sentenças, em que assi não guardarem as ditas Ordenações, sejam nenhuns. E o mesmo mandamos a todos os Desembargadores da Casa do Porto, Corregedores, Ouvidores e Julgadores, sob a mesma pena.` },
        { id: 'of1-tv-5', number: '5', text: `E havemos por bem, que quando os Desembargadores, que forem no despacho de algum feito, todos ou algum delles tiverem alguma duvida em alguma nossa Ordenação do entendimento della, vão com a duvida ao Regedor; o qual na Mesa grande com os Desembargadores, que lhe bem parecer, a determinará, e segundo o que ahi for determinado, se porá a sentença. E a determinação, que sobre o entendimento da dita Ordenação se tomar, mandará o Regedor screver no livro da Relação, para depois não vir em duvida. E se na dita Mesa forem isso mesmo em duvida, que ao Regedor pareça, que he bem de nol-o fazer saber, para a Nós logo determinarmos, nol-o fará saber, para nisso provermos. E os que em outra maneira interpretarem nossa Ordenações, ou derem sentenças em algum feito, tendo algum delles duvida no entendimento da Ordenação, sem ir ao Regedor, será suspenso até nossa mercê.` },
        { id: 'of1-tv-6', number: '6', text: `E havemos por bem, que quando se alguma parte quizer aggravar de algum Julgador, que lhe não guarda e cumpre alguma nossa Ordenação, se o caso, em que diz, que se não guardou, for de qualidade, que se logo póde aggravar per petição, ou instrumento de aggravo, ou Carta testemunhavel, o Juiz ou Juízes superiores, que do aggravo podem conhecer, proverão tambem sobre a execução desta Ordenação, e darão a pena della aos inferiores, não sendo o inferior nosso Desembargador. E se o Julgador, de que se a parte aggravar, for tal, que delle não possam aggravar, assi por ser interlocutoria, em que ao tempo, em que se pronuncia, não se possá aggravar, como por caber em sua alcada, quando for definitiva, ou sendo o Julgador nosso Desembargador; nestes casos, ou cada hum delles, o Regedor com cinco Desembargadores conhecerá do tal aggravo, em que se a parte aggrava de lhe não ser guardada nossa Ordenação, e executará em todo as penas nesta Lei conteúdas. E se o aggravo for de algum Desembargador da Casa do Porto, ou de algum Julgador de caso, que se delle houvera appellação, houvera de vir á dita Casa, o Governador com outros tantos Desembargadores della conhecerão disso, e darão á execução as penas desta Ordenação.` },
        { id: 'of1-tv-7', number: '7', text: `E porque as partes se não aggravem, como não devem, mandamos, que achando-se pelos Superiores, que do aggravo hão de conhecer, que se não aggravaram bem, sejam condenados nas custas em dobro, que se por causa do retardamento seguirem ás partes contrarias. E não havendo ahi parte contraria, sejam condenados em dous mil reis para as despesas da Relação.` },
        { id: 'of1-tv-8', number: '8', text: `E mandamos a todos nossos Desembargadores, que não conheçam dos feitos, que lhes claramente não pertencerem, e os remetam a seus Juízes competentes, tanto que requeridos forem per cada huma das partes, do dia, que pozerem nelle o primeiro desembargo, até oito dias primeiros, sob pena de pagarem ás partes as custas em dobro de todo o retardamento, e dos autos, que perante esses Juízes incompetentes forem feitos, por quanto os havemos por nenhuns. E o mesmo cumprirão os Desembargadores da Casa do Porto, Corregedores, Ouvidores, Juízes de Fóra, e Juízes Ordinarios da nossa cidade de Lisboa, sob a mesma pena.` },
        { id: 'of1-tv-9', number: '9', text: `Mandamos, que no caso, onde forem certos Desembargadores Juízes de algumas causas, assi como os do aggravo, e em alguma interlocutoria, ou incidente variarem, por onde seja necessário metter-se no feito outro Desembargador, ou Desembargadores, que os concordem, depois que fôr posta a dita interlocutoria, o feito tornará áquelle, que for de differente parecer; e conhecerá delle com os outros em tudo o mais, que se houver de processar, assi como conhecerá, se dos outros não variára, e será obrigado seguir o desembargo, que pelos outros foi acordado, postoque elle fosse de outra opinião. E isto mesmo se guardará nos outros feitos, que se despacharem nas mesas pelos Desembargadores, que o Regedor cada dia ordena, onde muitas vezes as interlocutorias são despachadas per diversos Desembargadores; porque serão obrigados os que derradeiramente vierem aos despachos dos ditos feitos, seguir as interlocutorias pelos outros postas, ou postoque já outra vez stivessem ao despacho das interlocu- torias, e fossem de contraria opinião. E isto se não entenderá quanto ao que toca á substancia da causa nas sentencas finaes, porque os Desembargadores, que houveram de despachar os feitos, em que são postas interlocutorias per outros, porão suas sentenças definitivas, como lhes parecer justiça, sem serem obrigados seguir as ditas interlocutorias postas per outros.` },
        { id: 'of1-tv-10', number: '10', text: `Item, mandamos, que postoque o Desembargador, que da causa conhecia, seja mudado, o feito não sáia da mão do Scrivão ordenado, salvo por suspeição ou por outro semelhante impedimento.` },
        { id: 'of1-tv-11', number: '11', text: `E para bom despacho e brevidade dos feitos civeis, mandamos, que quando em algum feito finalmente concluso e visto em Relação se pozer interlocutoria, para se haver de fazer alguma diligencia, o Juiz principal do feito ponha em lembrança, assinada pelos Desembargadores, que nelle forem, o que se fará, tanto que a interlocutoria se cumprir, e a diligencia vier feita de huma maneira, ou de outra, para então se screver a sentença no feito, e se assinar, segundo a dita lembrança, vendo-se sómente o que novamente accrescer, sem se tornar a ler todo o feito, a qual lembrança ficará em poder do Juiz do feito. E quanto ás lembrancas dos feitos crimes, se terá a ordem, que se dirá no Livro quinto, Titulo 124: Da ordem do Juizo nos feitos crimes, § 25: E em todos.` },
        { id: 'of1-tv-12', number: '12', text: `E quando per appellação, ou aggravo, ou per qualquer outro modo forem alguns feitos crimes á Relação, em que faltar alguma solemnidade, ou se proceder nelles per via de devassa, não sendo os casos, de que por bem de nossas Ordenações se pode devassar, ou que per qualquer outra causa se possam annullar, conforme ás Ordenações e Direito, sendo os casos taes e tão provados, que pareça, que convem a bem de justiça castigarem-se os culpados, se não annullem os ditos feitos e autos: e o Desembargador, que delles for Juiz, dará conta ao Regedor, o qual porá o caso em Mesa com os Desembargadores, que lhe parecer, para com informação do Desembargador Juiz da causa se supprirem os ditos defeitos, como for assentado pela maior parte dos Desembargadores, e se castigarem os delinquentes conforme a qualidade de suas culpas. E quanto aos feitos civeis, se guardará o que se dispõe no Livro terceiro, Titulo 63: Que os Julgadores julguem por a verdade sabida.` },
        { id: 'of1-tv-13', number: '13', text: `E por se evitarem os inconvenientes, que poderia haver, se os Desembargadores, que estão em huma Mesa, só per informações e relações de outros assinassem os despachos, que se poem em outra Mesa, assi em feitos crimes, como civeis, sem serem presentes aos ditos despachos, para ouvirem e conferirem huns com os outros as razões, per que se movem: mandamos que nenhum Desembargador assine no despacho, que se pozer em outra Mesa, em que não for presente, e o Regedor o não consentirá.` },
        { id: 'of1-tv-14', number: '14', text: `E quando os Desembargadores, que são obrigados tirar as inquirições nos feitos, de que são Juizes, conforme a Ordenação no Titulo 86: Dos Enqueredores, § 3: E quando forem occupados de modo que per si as não possam tirar, ou sendo as testemunhas de tal qualidade, que não devam ir a casa dos Desembargadores, ou acontecendo caso, por que pareça ao Regedor, que elles o não poderão fazer: committera o tirar das ditas inquirições a outros Officiaes, que para isso lhe parecerem idoneos.` },
        { id: 'of1-tv-15', number: '15', text: `Item, mandamos, que dous Desembargadores, que pelo tempo forem mais modernos na Casa da Supplicação, façam as audiencias aos feitos, que pertencem ao Juizo dos Aggravos e Appellações, e ao Juizo dos Feitos da Coroa e da Fazenda, e dos Ouvidores do Crime e Juiz da Chancellaria. E tendo algum delles impedimento, por que as não possam fazer, succederão nisso em seu lugar os Desembargadores, que ante delles forem mais modernos. E mandarão metter os feitos, que houverem de publicar, em um sacco perante si na Relação, o qual os Porteiros levarão á audiencia. E depois que os Desembargadores stiverem na séda, mandarão abrir o sacco, e tirar delles os feitos, e publicarão per si todas as sentenças, que nelles stiverem postas, e nãs as poderão haver por publicadas. E não commettirão as audiencias, que são obrigados a fazer, por serem mais modernos, a algum dos Advogados. E tendo justo impedimento, o farão saber ao Regedor, para que proveja outro Desembargador, que ante delles fôr mais moderno, que as faça. E o dito Regedor as não commettirá a algum Advogado, e os Advogados não acceitarão as taes commissões, sob pena de suspensão de seu Officio.` },
        { id: 'of1-tv-16', number: '16', text: `E os Desembargadores, que Nós aposentarmos ou escusarmos de ir à Relação, indo a ella, não terão voto, nem poderão ser em despacho algum, salvo tendo para isso especial Provisão nossa.` },
        { id: 'of1-tv-17', number: '17', text: `E porque os hospedes, que vão pousar com os Desembargadores, lhes impedem o despacho dos feitos, mandamos, que nenhum Desembargador agazalhe hospede em sua casa, salvo se for seu ascendente, ou descendente, ou irmão seu ou de sua mulher ou criados seus, ou amos; e fazendo o contrario, Nós lho estranhareṁos, e daremos a pena, que nos bem parecer. E o Regedor nos dirá, quando os Desembargadores assi o não cumprem. Não tolhemos porém, que os Desembargadores pousem huns com os outros, porque se não podem estorvar em seu despacho.` },
      ],
    },
    {
      id: 'titulo-vi',
      title: `VI. Dos Desembargadores dos Aggravos e Appellações da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-tvi-preambulo', number: 'Preâmbulo', text: `Aos Desembargadores dos Aggravos da Casa da Supplicação pertence conhecer igualmente per distribuição dos feitos, que per aggravo a elles vierem da Relação da Casa do Porto, de casos civeis, que passarem de quantia de cem mil reis em bens moveis, e de oitenta em bens de raiz. E tomarão outrossi conhecimento dos aggravos, que saírem do Juiz das auções novas da dita Casa do Porto, passando das ditas quantias. E conhecerão dos Aggravos dos Corregedores da nossa Corte, e do Juiz da India e Mina, e dos Corregedores da cidade de Lisboa, Juiz dos Alemães, Conservadores das Universidades de Coimbra e Evora, nos casos, que não couberem em suas alçadas. Dos quaes Aggravos tomarão conhecimento, segundo he conteúdo no terceiro Livro, no Titulo 8: Dos aggravos das sentenças definitivas: e isto se não entenderá nos aggravos e appellações, que saírem dante os Officiaes, que conhecem dos feitos da Fazenda da Universidade de Coimbra entre ella e os recebedores de suas rendas e seus fiadores e abonadores, e quaesquer outras pessoas: porque estes hão de vir direitamente ao Juizo de nossa Fazenda, como se dirá no Titulo 10: Dos Juizes de nossos feitos da Fazenda. E a maneira, que terão no despacho dos ditos Aggravos, he a seguinte.` },
        { id: 'of1-tvi-1', number: '1', text: `Sendo o feito sentenceado pelos Julgadores acima declarados, ou per outro, de que se possa aggravar para a Casa da Supplicação, se dous Desembargadores dos Aggravos se acordarem com a sentença dada pelos sobreditos, e a confirmarem, logo esse feito per esses dous assi concordantes seja findo e determinado, e se ponha a sentença. E se os ditos dous Desembargadores se acordarem ambos em revogar a tal sentença, vá o feito a outro Desembargador dos Aggravos por terceiro; e se acordar com os dous, porão sentença conforme a seu acordo; e se este terceiro for differente dos dous, vá o feito a quarto; e se concordar com os primeiros dous a revogar, ponha-se a sentença per elles tres; e se o quarto concordar com o terceiro, ou for em outra differente tenção, vá a quinto; e se o quinto concordar com alguma das duas tenções, ou a revogar, ou a confirmar, ponha-se sentença, segundo o que pelos ditos tres for concordado. E se for em outra tenção differente, em maneira que não sejam conformes tres em huma tenção, corra os mais dos Aggravos, se os hi houver, até se acordarem tres em huma tenção, como fica dito. E tanto que os ditos tres forem acordados em huma tenção, logo se ponha sentença, ou a confirmar, ou a revogar. E sendo visto o feito per todos os dos Aggravos, e não concordando os que assi são necessários para se pòr a sentença, e não houver mais Desembargadores dos Aggravos, assi por algum ser suspeito, como por outra qualquer maneira, o derradeiro delles o porá em mesa perante o Regedor, o qual verá se póde concordar os ditos Desembargadores, que suas tenções tem postas, para se pòr sentença; e não os podendo concordar, chamará á dita mesa os mais Desembargadores, que lhe bem parecer, e tomadas as vozes dos ditos Desembargadores dos Aggravos, que já tem visto o feito, e postas tenções com os mais, que na mesa stiverem, o determinarão segundo forem as mais vozes, e assi se porá a sentença.` },
        { id: 'of1-tvi-2', number: '2', text: `E em caso que os primeiros dous Desembargadores sejam differentes em suas tenções, e hum for em confirmar as sentenças, e outro em revogar, será o feito dado a terceiro. E acordando-se com o que for em confirmar, porá logo a sentença confórme ao acordo de ambos. E se o terceiro se acordar com o que he em revogar, ou for em outra nova tenção, então irá á quarto, e se terá a fórma, que dissemos no paragrapho precedente.` },
        { id: 'of1-tvi-3', number: '3', text: `E porque muitas vezes nas tenções são concordes em parte, e differentes em outra parte, ou concordes no principal, e differentes nas custas, por bem da qual differença vai a outros mais Desembargadores, segundo acima fica dito; mandamos, que o Desembargador, a que assi for por terceiro, quarto, ou quinto, ponha sua tenção sómente na parte, em que for a differença; porque quanto na parte, em que já os outros Desembargadores ficam concordes, he adquirido direito áquelle, por quem são concordes; e segundo as ditas tenções se ha de pór a sentença per os que concordaram, postoque na outra parte, ou nas custas, em que era a differença, se haja de pór pelos mais Desembargadores, que pozeram as mais tenções: a qual sentença se porá em aquillo, que acordarem sobre a differença, que foi a elles. E porque ás vezes são conformes tres Desembargadores na decisão do caso principal, e differentes nas custas, tanto que dous se acordarem nas custas, porão sentença, sem ir a mais Desembargadores. E sendo todos differentes na condenação das custas, irá o feito a outro Desembargador, no que toca ás ditas custas sómente; e como dous fôrem conformes, se ponha a sentença.` },
        { id: 'of1-tvi-4', number: '4', text: `E os ditos Desembargadores dos Aggravos despacharão per tenções todos os instrumentos de aggravo, e Cartas testemunhaveis, que a elles vierem dos Julgadores das Comarcas da repartição e districto da Casa da Supplicação, como abaixo se dirá, não sendo instrumentos ou Cartas testemunhaveis, que pertençam a feitos crimes, ou que specialmente per nossas Ordenações pertençam a outros Julgadores. E como fôrem dous concordes a confirmar, ou revogar, porão o desembargo segundo suas tenções. E se forem differentes, irá a terceiro, ou quarto, e dahi por diante até serem dous concordes. E quando os aggravos forem do Juiz receber appellação á parte contraria, quer de sentença definitiva, quer de interlocutoria, tomarão os ditos Desembargadores conhecimento do tal instrumento, ou Carta testemunhavel, e não outro algum Julgador. E no caso que alguns instrumentos forem tirados dante alguns Desembargadores, que a algumas partes mandarmos com alçada, postoque Presidente levem, não tomarão conhecimento dos taes aggravos, mas virão a Nós direitamente.` },
        { id: 'of1-tvi-5', number: '5', text: `E não tomarão conhecimento dos requerimentos de aggravos, sem as partes nelles fazerem declaração, como aggravam para os ditos Desembargadores. A qual declaração farão nos ditos requerimentos, ou petições, ou per termo nos autos.` },
        { id: 'of1-tvi-6', number: '6', text: `Os Desembargadores dos Aggravos conhecerão das petições de aggravo, que forem dadas ao Regedor, segundo em seu titulo he ordenado, e assi dos feitos, que per desembargo, posto nas ditas petições, vierem á Relação. E conhecerão dos aggravos, que a elles vierem per petições, ou instrumentos e Cartas testemunhaveis, de quaesquer lugares, que estejam dentro das cinco legoas da cidade de Lisboa. E os aggravos, de que per petição podem conhecer, são os seguintes.` },
        { id: 'of1-tvi-7', number: '7', text: `De todas as interlocutorias e mandados de quaesquer Juizes, ou Justiças da cidade de Lisboa (nos casos, de que se delles póde aggravar per petição, que serão declarados no Livro terceiro, Titulo 20; Da ordem do Juizo) não tomarão conhecimento outro algum Julgador da dita cidade, nem os Corregedores da Corte; mas irão direitamente aos Desembargadores dos Aggravos, não sendo sobre cousas de nossa Fazenda, ou de nossos direitos, porque destes conhecerão os Juizes, a que pertencer.` },
        { id: 'of1-tvi-8', number: '8', text: `Item, de todos os termos e mandados, que quaesquer Desembargadores da Casa da Supplicação mandarem cada hum per si só nas audiencias, ou fóra dellas em feito civel, ou crime, que se ha de despachar em Relação, e de que não ha de haver aggravo da sentença definitiva: e bem assi de qualquer interlocutoria, que cada hum dos Desembargadores, que per seu Regimento per si só póde pôr em feito crime, postoque o haja de despachar em Relação, e pozer a dita interlocutoria per si só, poderão aggravar per petição para os ditos Desembargadores.` },
        { id: 'of1-tvi-9', number: '9', text: `E bem assi se poderá aggravar das interlocutorias e mandados, que o Corregedor da Corte dos feitos civeis pozer, ou mandar nos feitos, de que elle conhecer per aução nova, ou outro Desembargador, a que commettermos algum feito, que per si só desembargue, sendo as ditas interlocutorias, ou mandados, em que se não receba per cada hum dos sobreditos alguma contrariedade, defesa, replica, treplica, ou parte de cada huma dellas, ou sendo a interlocutoria, ou mandado sobre dilação grande, ou pequena, que se der para fóra do Reino, ou sendo sobre incompetencia do juizo, quer pronuncie que recebe a excepção, quer não, e assi depois de recebida, quer se pronuncie por Juiz competente, quer não. E assi mais se poderá dos sobreditos aggravar nos casos conteúdos no Livro terceiro, Titulo 20: Da ordem do Juizo.` },
        { id: 'of1-tvi-10', number: '10', text: `E por quanto ás vezes os Desembargadores, que as audiencias fazem, e assi os que per seu Regimento cada hum per si só ha de despachar, por as partes não poderem aggravar dos termos e mandados, que na audiencia se haviam de mandar, e assi das interlocutorias, que per elles só haviam de passar, de que podiam aggravar, não querem mandar sobre o aggravar, nem querem despachar cada hum per si só, confórme a seu Regimento, mas mandam fazer os feitos conclusos sobre os taes termos, e os despacham em Relação, e assi despacham em Relação o que per cada hum sómente havia de ser despachado, por tolherem o aggravo: querendo evitar isso, mandamos, que se cada hum dos Desembargadores, que as audiencias fazem, nos termos, que nas audiencias se soem mandar, assi como dilações ás partes, e outros semelhantes, e bem assi nas cousas, que per seu Regimento hão de despachar cada hum per si, e de que podem aggravar, despacharem os ditos termos, mandados, ou sentenças em Relação, que em taes casos, sem embargo de serem despachados em Relação, as partes possam aggravar dos taes despachos postos em Relação, assi como poderão aggravar, se per si só desembargaram tal interlocutoria, ou termo na audiencia.` },
        { id: 'of1-tvi-11', number: '11', text: `E as petições, per que se aggravarem de cada hum dos sobreditos Desembargadores, ou Julgadores, conteúdos neste titulo, serão assinadas pelo Procurador do feito. E achando-se que he contraria aos autos, e não he feita na verdade do que no feito se contém, ou he feita manifestamente contra Direito, ou que he frivola, e de materia, per que pareça que não ha a parte aggravada, pagará o tal Procurador por cada petição, que assi fizer, dous mil reis para as despesas da Relação, e não será admittido a servir, sem mostrar como os tem pago.

Appellações.` },
        { id: 'of1-tvi-12', number: '12', text: `Item, os ditos Desembargadores dos Aggravos tomarão conhecimento de todas as appellações de casos civeis, que sairem, e vierem a elles dante os Juizes do Civel, e dos Orfãos da cidade de Lisboa, e do Ouvidor da Alfandega, Provedor dos Residuos e Capellas, e do Provedor dos Orfãos, e do Conservador da Moeda, e das Ilhas, e do Reino do Algarve, e das Comarcas de antre Tejo e Guadiana, e da Estremadura, tirando as Correições de Coimbra e Esgueira, que hão de ir á Casa do Porto; e assi conhecerão das appellações da Comarca de Castel-branco, e dos feitos de aggravo do Conservador da Universidade de Coimbra nos casos, que não couberem em suas alçadas. E assi tomarão conhecimento dos instrumentos de aggravo e Cartas testemunhaveis de casos civeis, que vierem de todos os sobreditos, e que não couberem em suas alçadas.` },
        { id: 'of1-tvi-13', number: '13', text: `No despacho das appellações terão a maneira seguinte. Nas que forem até quantia de dez mil reis afóra as custas, como fôrem dous confórmes a confirmar, ou a revogar, porão sentença; e não sendo confórmes, irá o feito a terceiro, e aos mais que cumprir. E passando a quantia de dez mil reis até dezaseis mil reis nos bens de raiz, e vinte nos bens moveis, se porá a sentença, tanto que fôrem dous confórmes em confirmar, ou tres em revogar. E os dias de apparecer despacharão em mesa, e sendo dous confórmes, se porá a sentença; e no conformar dos votos das appellações e dos instrumentos de aggravo, ou Cartas testemunhaveis, e condenação de custas, se terá a ordem, que acima stá dito nas tenções dos feitos de aggravo.` },
        { id: 'of1-tvi-14', number: '14', text: `Nos feitos, que vierem per aggravo aos Desembargadores, sendo o primeiro, a que for distribuido, em parecer, que o feito não stá em termos para se despachar finalmente, mas que he necessario fazer-se alguma diligencia, para a qual se deva pôr alguma interlocutoria, não dará o feito a outro Desembargador; mas leva-lo-ha à Relação, e com outro Desembargador dos Aggravos, se a dita interlocutoria não tiver respeito a revogar, ou se o tiver, com dous Desembargadores dos Aggravos, quaesquer que na mesa se acharem, vejam o feito, e determinem a dita interlocutoria, como lhes parecer justiça. E concordando nella, se ponha o desembargo, como fôr acordado. E não concordando os outros Desembargadores na interlocutoria, da maneira que era tenção do primeiro Juiz, se ponha o desembargo, segundo pelos mais fôr acordado, sendo sempre dous confórmes na interlocutoria, que não tiver respeito a revogar, e na que o tiver, serão tres confórmes. E sendo os outros Desembargadores em parecer, que se não deve pôr interlocutoria, mas que se deve o feito de despachar finalmente, assi se porá o desembargo, e tornará o feito ao Desembargador, que o primeiramente vio, para que ponha nelle sua tenção final. Porém se a dita diligencia e interlocutoria não for pedida per alguma das partes, mas o Desembargador a mover de seu Officio, e fôr acordado pelos outros que he escusada, far-se-ha assento disso, assinado no feito pelos Desembargadores, que na dita interlocutoria forem, para depois não vir em duvida aos outros Desembargadores, que o feito houverem de ver, se se devia fazer a dita diligencia. E sem publicação da dita determinação e assento, ficará logo o feito com elles, para pôr sua tenção final, sem se fazer a dita diligencia. E esta mesma maneira se terá, postoque o primeiro tivesse posto sua tenção final, se o segundo, ou terceiro for em parecer de interlocutoria: porque o que de tal parecer for, levará o feito à Relação, para se ver per elle, e pelos outros primeiros, que tenção final tiverem posta, se se podem concordar; e se não, com outros Desembargadores dos Aggravos; e não os havendo, ou sendo suspeitos, per outros, que o Regedor ordenar, e sempre se terá a maneira, que no primeiro Desembargador he dito. E isto mesmo se guardará nas sentenças, que vem per aggravo da Relação do Porto, em que não receberam alguns artigos de embargos, ou de nova razão, ou negaram licença à parte para os poder fazer; se o primeiro Desembargador, a que o feito for distribuido, ou o segundo, for em recebimento dos ditos artigos, o porá em mesa, e não porá tenção.` },
        { id: 'of1-tvi-15', number: '15', text: `E quando algum dos ditos Desembargadores, a que for distribuida alguma appellação, e passar da quantia de dez mil reis afóra as custas, for de parecer, que se haja de fazer alguma diligencia, a levará à Relação, e a porá em mesa com dous Desembargadores dos Aggravos, ora a interlocutoria leve tenção a revogar, ou a confirmar a sentença. E sendo todos tres confórmes, se porá o desembargo como fôr acordado. E não concordando, se porá com tantos, até que haja tres confórmes, guardando em todo o mais a ordem e fórma, que he dada acima nos feitos dos aggravos. E nos feitos, que não passarem de dez mil reis, o Desembargador, que for em parecer de interlocutoria, a porá com outro: e sendo ambos confórmes, porão o desembargo, e não o sendo, o porá com terceiro, para que sejam dous confórmes.` },
        { id: 'of1-tvi-16', number: '16', text: `E tanto que o feito for concluso, depois de o Desembargador o ter visto, screverá sua tenção em hum papel apartado, o qual não ajuntará ao feito, e no fim da tenção porá o dia, mez e anno, em que a screveo, e a assinará; e elle mesmo a levará à Relação, e mandará levar o feito, e em Relação o entregará ao Desembargador seguinte, e com elle lhe entregará a tenção, declarando ao pé della o dia, mez e anno, em que lh'a entrega com o feito. E o Desembargador, que o dito feito e tenção receber, a levará para casa em seu poder, sem a entregar a pessoa alguma. E depois de o segundo Desembargador ter visto o feito, se concordar com a tenção do primeiro, porá a sua, e a levará à Relação com o feito. E se for de qualidade, que baste serem dous confórmes, poráo nelle sentença; e não o sendo, irá a terceiro, o qual terá a mesma ordem. E farão coser as tenções perante si, e depois de cosidas, poráo a sentença, e no fim della declararáo o dia, mez e anno, em que se screveo, e assinarão. O que se fará no dia da audiencia, em que a sentença se houver de publicar, para que antes de publicada não ande o feito em poder de pessoa alguma, que possa saber e descobrir o conteúdo nas tenções e sentença. E esta mesma maneira terá o terceiro, quarto, ou mais Desembargadores, a quem o feito houver de ir, até serem confórmes tantos, que bastem para se a sentença haver de por, como acima dito he. E o que se diz nos feitos do aggravo, se fará isso mesmo nos feitos das appellações.

S - p. 1 t. 5 l. 11 pr., e § 1 e 2.` },
        { id: 'of1-tvi-17', number: '17', text: `E os Desembargadores, que os ditos feitos despacharem, terão em muito segredo as tenções, antes de as sentenças serem publicadas, sem as praticar com pessoa alguma, postoque seja Desembargador da Casa, não sendo algum dos que no feito forem Juizes, porque com esses poderão praticar o que lhes parecer necessario para despacho do dito feito. E em quanto tiverem as tenções em suas casas, as terão fechadas de sua mão, de maneira, que as não possa ver pessoa alguma. E sendo negligentes no segredo, e cousas acima ditas, lhes será estranhado, segundo a qualidade da culpa, ou negligencia, que nisso tiverem.

S - p. 1 t. 5 l. 11 § 2.

O primeiro impõe a pena de nullidade ás tenções não escriptas pelo proprio Desembargador, e o segundo validava a tenção do Desembargador fallecido, se ao tempo da morte tinha passado o feito ao immediato.` },
        { id: 'of1-tvi-18', number: '18', text: `E mandamos, que se depois de algum Desembargador ter posta sua tenção, se finar, ou for privado do Officio, tal tenção seja havida por nenhuma, e irá o feito a outro Desembargador dos Aggravos seguintes. E esta maneira se terá em todos os outros feitos, que per quaesquer outros Desembargadores se houverem de despachar per tenções. E sendo algum Desembargador, que tenha posta sua tenção, suspenso, será sua tenção valiosa. E sendo absente do Reino, não valerá a tenção, que tiver posta, salvo se, stando Nós fóra deste Reino, o dito Desembargador for à nossa Corte per nosso mandado, ou a seus requerimentos, ou negocios, porque não he razão, indo a ella negociar o que lhe cumpre, com animo de tornar, haver de ser nulla a tenção, que tiver posta.` },
        { id: 'of1-tvi-19', number: '19', text: `Item, darão ajuda de braço secular em Relação no districto da dita Casa, citadas as partes, e visto o processo, achando que foi ordenadamente feito. A qual darão nos casos, e na fórma, que se dirá no Livro segundo, Titulo 8: Da ajuda de braço secular.` },
        { id: 'of1-tvi-20', number: '20', text: `Item, os ditos Desembargadores não tomarão conhecimento das appellações, cabendo na alçada dos Julgadores, postoque per alguma das partes lhes não seja apontado; e todo o processado depois do recebimento da appellação será nenhum, e mandarão cumprir as sentenças, de que assi for appellado. E a parte, que de tal sentença appellou, postoque o Julgador recebesse a appellação, e a outra parte o não contradissesse, pagará as custas, ou o Julgador, que a mal recebeo, qual aos ditos Desembargadores parecer. E o mesmo será nos aggravos das sentenças definitivas.` },
        { id: 'of1-tvi-21', number: '21', text: `E quando os Desembargadores houverem de emendar alguma sentença, que a elles vier per aggravo, ou appellação, não dirão: Emendando nisto, e accresccentando nistoutro; mas dirão, que não he bem julgado pelo Ouvidor, ou Juiz, ou per todos; e emendando as ditas senten- cas, ou revogando, declararão as causas, por que se assi movem.` },
        { id: 'of1-tvi-22', number: '22', text: `E quando mandarem emendar alguns artigos, não declararão as cousas, em que se hão de emendar, porque não devem ensinar às partes, nem a seus Procuradores, como hão de formar seus artigos.` },
      ],
    },
    {
      id: 'titulo-vii',
      title: `VII. Dos Corregedores da Corte dos feitos crimes`,
      type: 'articles',
      articles: [
        { id: 'of1-tvii-preambulo', number: 'Preâmbulo', text: `Aos Corregedores da Corte do Crime pertence o conhecimento por nova argum, de todos os malefícios commettidos no lugar, onde Nós stivermos, e de redor cinco legoas: com tal declaração, que se hum Cortezão commetter algum malefício no lugar, onde a nossa Corte stiver, contra outro Cortezão, ou contra algum morador no mesmo lugar, e a cinco legoas de redor, ou contra algum de fóra do dito lugar, e este Cortezão for accusado por o tal crime perante o Corregedor, onde quer que a Corte então stê, que elle não possa declinar seu juizo, e pedir que o remettam aos Juízes do lugar, onde o delicto fôr commettido.` },
        { id: 'of1-tvii-1', number: '1', text: `E se a parte, ou Justiça o quizer accusar perante os Juízes do lugar, onde o delicto fôr commettido, e elle requerer que o remettam ao Corregedor da Corte, mandamos que lhe seja remettido, ora seja accusado preso, ora solto, postoque a outra parte o não consinta. Porém quando ambas as partes consentirem, que o feito se trate perante os Juízes do dito lugar, conhecerão delle.` },
        { id: 'of1-tvii-2', number: '2', text: `E se o tal delinquente quizer tomar Carta de seguro, a poderá tomar perante o Corregedor da Corte. E querendo-a tomar perante os Juízes do lugar, onde o crime (stando ahi a Corte) fôr commettido, o Corregedor lhe dará com clausula, que se a parte antes o quizer accusar perante elle Corregedor, que o venha accusar a certo tempo, que lhe na dita Carta será assinado. E se parte alguma não accusar tal delinquente, ou por a não haver, ou não querer accusar, e for tal caso, em que haja lugar a Justiça, queremos, que se não livre, senão perante o Corregedor da Corte.` },
        { id: 'of1-tvii-3', number: '3', text: `E se este, que o crime commetter no lugar, onde assi stiver a Corte, não for Cortezão, quer seja morador no lugar do malefício, quer em outra parte, poderá ser accusado na Corte, ou no lugar do malefício, como o accusador antes quizer, quer o tal accusador seja Cortezão, quer morador no lugar, onde a Corte stiver, ou fóra delle, em qualquer outra parte.` },
        { id: 'of1-tvii-4', number: '4', text: `E se o tal delinquente quizer tomar Carta de seguro, e o offendido for morador no lugar do malefício, ou em seu termo, de-lha o Corregedor para os Juízes do dito lugar do malefício com a sobredita clausula, que se o ante quizer accusar perante elle Corregedor, que o venha accusar a certo tempo, que lhe na Carta seja assinado; se o offendido for morador fóra do lugar, onde for feito o malefício, e o delinquente quizer Carta de seguro, de-lha o Corregedor para si. E se depois que perante elle o offendido vier à citação, disser que antes quer accusar o delinquente no lugar do malefício, remetta-os lá, assinando certo tempo, a que lá pareçam. E se não houver parte, queremos, que o tal delinquente possa ser accusado perante as Justiças do lugar, onde o crime fôr commettido, ou perante os Corregedores da Corte, como elle antes quizer.` },
        { id: 'of1-tvii-5', number: '5', text: `Porém não tolhemos, que em todos os casos sobreditos os ditos Corregedores com parecer do Regedor em Relação, e acordo dos Desembargadores, que elle ordenar, possam mandar vir à Corte os ditos feitos, quando entenderem, que por algum bom respeito, e bem da Justiça se deve assi fazer, ora os delinquentes sejam presos, ora soltos, mandando isso mesmo vir as pessoas dos accusados à Corte soltos, ou presos, como lhes bem e razão parecer.` },
        { id: 'of1-tvii-6', number: '6', text: `E bem assi, se alguns Procuradores, ou Scrivães, que procuram e servem em nossa Corte e Casa da Supplicação perante os nossos Officiaes da Justiça, e os nossos moradores, que de Nós hão moradia, ou mantimento no tempo, em que o vencem: e bem assi todos os outros, que com cada hum dos sobreditos continuadamente viverem, e com elles andarem em nossa Corte e Casa da Supplicação, commeterem qualquer maleficio fóra da Corte, poderão ser accusados perante os ditos Corregedores, não os querendo antes accusar as partes nos lugares, onde commetteram os maleficios. E não havendo partes, que os accusem, poderão ser accusados perante as Justiças do lugar, onde os maleficios commetteram, ou perante os Corregedores da Corte, como elles antes quizerem.` },
        { id: 'of1-tvii-7', number: '7', text: `Item, mandarão prender, e trazer à cadeia da Corte todos aquelles, de que lhes for querelado de maleficios commettidos na Corte, e cinco legoas de redor, sendo as querelas taes, por que devam ser presos, com tanto que sejam primeiro certificados, que na Corte, ou dentro das cinco legoas foram commettidos os taes maleficios, e conhecerão delles no modo, que em cima dissemos.` },
        { id: 'of1-tvii-8', number: '8', text: `E assi mesmo mandarão prender e trazer à cadeia da Corte os de que lhes for querelado, ou forem culpados em casos de traição, heresia, aleive, moeda falsa, sodomia, tirada de presos da cadeia, aindaque na Corte não hajam commettido os taes maleficios, sendo commettidos no districto da Casa da Supplicação. E destes casos não darão Carta de seguro, senão os Corregedores da Corte, as quaes passarão dirigidas para si mesmos. E nos outros maleficios fóra da Corte, de que lhes for dada querela, ou elles tiverem culpas obrigatorias, para deverem ser presos, mandarão que o sejam, e se despachem nas terras e lugares, onde se disser haverem commettido os maleficios; os quaes mandarão prender per seus Alvarás, como diremos no Livro quinto, no Título 419:

Como serão presos os malfeitores. Os quaes Alvarás não assinarão, até lhes as partes mostrarem os traslados das querelas, scriptas e assinadas pelo Scrivão, que as tiver; e nos ditos Alvarás se fará menção, como as partes querelosas levam os ditos traslados. Porém, se elles tiverem informação, que os malfeitores são taes pessoas, ou acostadas a taes, que razoadamente os Juízes dos ditos lugares não possam delles fazer cumprimento de justiça, commetter-los-hão aos Corregedores das Comarcas, que façam delles direito, em modo que a justiça não pereça. E esta mesma maneira terão nos maleficios, de que lhes forem requeridas Cartas de seguro.` },
        { id: 'of1-tvii-9', number: '9', text: `E sendo as partes ambas moradores nas Comarcas assinadas à Casa do Porto, não poderão querelar diante dos Corregedores da Corte, nem elles lhes receberão querelas, salvo quando pela qualidade das causas, ou das pessoas Nós o commetermos a cada hum delles em particular. Porém se algum morador das ditas Comarcas commetter algum delicto nas Comarcas do districto da Casa da Supplicação, poderá a parte offendida querelar diante dos Corregedores da Corte, e elles tomarão conhecimento das ditas culpas, e as determinarão como for justiça.` },
        { id: 'of1-tvii-10', number: '10', text: `Item, darão Cartas de seguro em caso de morte de homem, commettido nos lugares do districto da casa da Supplicação, e outro algum Julgador as não passará, e irão dirigidas para elles mesmos. E das mortes acontecidas na India passarão Cartas de seguro dirigidas para Juizes competentes, perante os quaes se os ditos seguros livrarão. E aos moradores das Ilhas, e stantes em ellas, darão Cartas de seguro em todos os casos commettidos nellas, postoque sejam de morte, e Era essa carta uma promessa judicial, pela qual o réo, sob certas condições, deixava de ser preso até finalisar o processo. Havia a Carta de Seguro negativa e confessativa: a primeira quando o réo negava o facto de que era arguido, e a segunda quando confessava-o allegando legitima defesa. Em certos crimes não era concedida.

Era, emfim, um recurso que tinha sua utilidade, e não houve discrição em extingui-lo de todo entre nós.

irão dirigidas para os Juizes das ditas Ilhas, onde os delitos forem commettidos.` },
        { id: 'of1-tvii-11', number: '11', text: `Darão assi mesmo Cartas de seguro de resistencia, ou offensa, que se diga ser feita contra algum Official da Justiça; e outro algum Julgador as não passará em nossos Reinos, salvo o Corregedor do Crime da Casa do Porto no seu districto, e irão dirigidas para elles mesmos. Nas quaes Cartas se porá clausula, que se o dito Official da Justiça antes quizer accusar o delinquente no lugar, onde for feito o malefício, que o possa fazer. E não querendo o dito Official accusar, ou accusando na terra, desistir da accusação, mandamos, que o feito seja remetido aos ditos Corregedores da Corte, para nelle procederem, e o determinarem em Relação, como for direito.` },
        { id: 'of1-tvii-12', number: '12', text: `E de todos os outros malefícios commettidos fóra da Corte, nas Comarcas e lugares da jurisdição da Casa da Supplicação, darão assi mesmo Cartas de seguro, dirigidas para os Juizes dos lugares, onde se disserem os malefícios serem commettidos: com tanto que não sejam dos malefícios acima ditos, de que as Cartas de seguro hão de passar para si mesmos, nem dos commettidos pelos moradores das Ilhas, nos lugares deste Reino, dos quaes havemos por bem, que dirijam as Cartas para si, e conheçam dos ditos casos.` },
        { id: 'of1-tvii-13', number: '13', text: `E não darão Cartas de seguro nos erros dos Officios aos Tabellias, porque dar as taes Cartas pertence ao Juiz da Chancellaria: salvo quando a Corte stiver apartada da Casa da Supplicação, porque então o Corregedor, que na Corte andar, dará as ditas Cartas de seguro aos Officiaes da Corte, e do lugar, onde ella stiver, e cinco legoas ao redor, daquelles erros, de que o conhecimento pertencerá ao Juiz da Chancellaria, se a Casa stivera no lugar da Corte: o qual Corregedor conhecerá dos feitos dos ditos Officiaes com os Julgadores, que Nós ordenarmos.` },
        { id: 'of1-tvii-14', number: '14', text: `E qualquer pessoa, que tiver desembargo para Carta de seguro, poderá andar com elle seguro tres dias, como diremos no Livro quinto, no Titulo 129: Das Cartas de seguro.` },
        { id: 'of1-tvii-15', number: '15', text: `Item, os ditos Corregedores desembargarão todos os feitos e processos crimes, que perante elles se tratarem, e assi os instrumentos e Cartas testemunhaveis sobre feitos crimes, que vierem per aggravo dos lugares e Comarcas da jurisdição da Casa da Supplicação. E quaesquer outros feitos crimes, que dante outros quaesquer Juizes á Corte vierem per remissão nos casos, em que per bem de nossas Ordenações se póde fazer a tal remissão; os quaes desembargarão em Relação com os Desembargadores, que pelo Regedor fôrem em cada hum dia ordenados, conforme ao que fica dito no Titulo 1: Do Regedor. E no despacho dos ditos feitos terão a ordem, que he dada aos Ouvidores do Crime da dita Casa. E as interlocutorias dos ditos feitos e processos, que perante elles se tratarem, poderão os Corregedores per si sós pôr. E quando as assi sós pozerem, poderá cada huma das partes aggravar para a Relação per petição. E as contrariedades, ou defesas de feitos crimes despacharão sempre em Relação, conforme ao que se dirá no Livro quinto, Titulo 124: Da ordem do Juizo nos feitos crimes.` },
        { id: 'of1-tvii-16', number: '16', text: `Item, conhecerão de quaesquer aggravos, que a elles per petição vierem, de feitos crimes, dante quaesquer Julgadores, que de casos crimes conhecerem no lugar, onde a Corte stiver, e até cinco legoas ao redor (tirando aquelles, que, per special privilegio, tiverem de não responderem per petição aos ditos Corregedores); os quaes per si sós poderão mandar, que respondam, e desembargarão os ditos aggravos em Relação. E isto não sendo aggravos, que saiam dos Julgadores da cidade de Lisboa, porque destes pertence o conhecimento aos Desembargadores dos Aggravos.` },
        { id: 'of1-tvii-17', number: '17', text: `E se algum malfeitor de grave feito vier perante cada hum dos ditos Corregedores, de que elles hajam tal informação per evidentes indícios, per que lhes pareça, que deve logo ser mettido a tormento, e que sendo spaçado, se poderá aperceber o dito preso em tal maneira, que depois a verdade não poderá ser tão bem sabida: em tal caso, se o quizer metter a tormento, falle primeiro com o Regedor, e com alguns Desembargadores, que o dito Regedor para isso fará apartar logo, e com acordo dos sobreditos o poderá fazer, e de outra maneira não.` },
        { id: 'of1-tvii-18', number: '18', text: `Item, tomarão conhecimento, e despacharão per si sós per auçào nova na Corte, e a cinco legoas ao redor, as penas de sangue, assi de feridas, como de mortes de homens, e penas de armas, e das armas perdidas, e de excommungados, que per nossos Meirinhos forem presos: e de todas as outras penas, que per nossas Ordenações, ou mandados forem postas por alguns casos, em que não seja posta outra pena de degredo, ou corporal, sómente a pecuniaria. E das outras penas pecuniarias, que com pena de degredo, ou corporal forem postas, conhecerão em Relação. E das que per si sós hão de conhecer, não farão longos processos. E do que sobre isso determinarem, poderão as partes aggravar per petição à Relação para os Desembargadores dos Aggravos. E o que per elles fôr acordado em Relação, serão os ditos Corregedores obrigados cumprir e mandar dar à execução.` },
        { id: 'of1-tvii-19', number: '19', text: `Item, passarão as Cartas, per que damos os Officios de Meirinhos das cadêas da Corte e dos Meirinhos das Comarcas e Carcereiros, que Nós dermos.` },
        { id: 'of1-tvii-20', number: '20', text: `Item, darão Cartas de segurança Real na fórma, que diremos no Livro quinto, Titulo 428: Das seguranças Reaes.` },
        { id: 'of1-tvii-21', number: '21', text: `Item, enquererão nos lugares, onde Nós stivermos, e onde a Casa da Supplicação sem Nós stiver, sobre todos os Officiaes da Justiça, per os Capitulos, e na fórma conteúda no Titulo 65: Dos Juizes Ordinarios. E se já sobre elles as inquirições forem tiradas naquelle anno pelos Corregedores das Comarcas, ou Juizes, provejam as ditas inquirições; e achando que não foram tiradas como deveram, tirem outras, e procedam contra os culpados em maneira, que hajam castigo de seus erros e culpas. E assi devassarão cada seis mezes sobre os Carcereiros e Guardas da Cadêa da Corte, se vendem pão, vinho, ou outra cousa alguma aos presos per si, ou per outrem. E procederão contra os culpados à execução das penas conteudas no Titulo 33: Do Carcereiro da Corte.` },
        { id: 'of1-tvii-22', number: '22', text: `Item, farão correição nos lugares, onde Nós stivermos, e outra alguma Justiça não fará, postoque o lugar, onde Nós stivermos, seja da Rainha, ou de qualquer outro Senhor de terras, indaque nas ditas terras stêm seus Ouvidores. Porque onde os ditos Corregedores stão, que principalmente representam nossa pessoa, não póde outra alguma Justiça fazer correição, nem conhecer dos feitos, que aos ditos Corregedores pertencem.` },
        { id: 'of1-tvii-23', number: '23', text: `Outrosi, mandamos aos ditos Corregedores, que em todas as Cartas, que passarem, para se haverem de fazer algumas execuções, ou diligencias, seja posto termo razoado aos Corregedores das Comarcas, Ouvidores, ou Juizes, que as ditas execuções, ou diligencias houverem de fazer, que as façam no dito termo, e as enviem pelos Caminheiros, que lhes as Cartas presentarem, sob alguma razoada pena, que lhes per elles Corregedores seja posta, segundo a qualidade do negocio, ou caso. A qual pena será para os ditos Caminheiros, se a elles demandarem; e não a demandando elles, seja para quem a demandar. As quaes Justiças mandamos, que cumpram em tudo o que pelos ditos Corregedores lhes for mandado, dentro no termo, que lhes for assinado, sob as penas postas pelos ditos Corregedores.` },
        { id: 'of1-tvii-24', number: '24', text: `Item, os ditos Corregedores farão duas audiencias publicas em cada semana, às terças e sextas-feiras à tarde. E as não cometterão a pessoa alguma; e tendo impedimento, o farão saber ao Regedor para prover nisso.` },
        { id: 'of1-tvii-25', number: '25', text: `Tirarão per si as devassas das mortes, ou ferimentos, que acontecerem no lugar, onde Nós stivermos, ou a Casa da Supplicação, acudindo a isso com muita diligencia, a qualquer hora que o caso acontecer. E farão todas as diligencias para os culpados serem presos, tomando informação pelos feridos e pelos parentes dos mortos, e donde procederam os casos, e se sabem, ou presumem quem são os culpados, perguntando todas as testemunhas, que tiverem per informação, que do caso Pegas, no commentario à Ord. deste liv. 2 t. 6 n. 6, exprime-se, à respeito dos Ouvidores, desta sorte: "Nos plerumque auditores dicimu.s vel qui à Reje, non tamquam Rege, jurisdictionem habet."

Os Ouvidores não representavão o Rey, como os Corregedores, o que bem exprime este paragrafo, e o 8 do liv. 2 t. 45.

podem saber. E as devassas de morte não commetterão a ninguem. Porém as dos ferimentos, depois de terem per si feitas as diligencias acima ditas, constando-lhes que os ferimentos não são de morte, nem de pessoas de qualidade para elles per si as haverem de tirar, as poderão commetter a qualquer Julgador do lugar, onde Nós stivermos, ou a dita Casa da Supplicação, ou a hum Enqueredor, que as tire com hum Scrivão dante elles. E os outros Julgadores, que per obrigação de seus Officios hão de tirar as devassas de mortes e ferimentos, as tirarão per si pelo sobredito modo, sem as commetterem a outrem.` },
        { id: 'of1-tvii-26', number: '26', text: `Item, cada hum dos ditos Corregedores correrá a cidade de Lisboa de noite, huma vez ao menos cada semana.` },
        { id: 'of1-tvii-27', number: '27', text: `E quando Nós stivermos fóra da cidade de Lisboa, e o Contador das custas for suspeito, ou per algum impedimento outro não poder fazer as contas, o Corregedor da Corte, que comnosco stiver, as commetterà a huma pessoa, que bem e sem suspeita as possa fazer. E se depois da conta feita, as partes allegarem sobre ella algum erro, o dito Corregedor conhecerá delle, e o determinará, como lhe bem parecer. E aggravando-se alguma parte de sua determinação, Nós proveremos quem do dito aggra­vo haja de conhecer. E assi conhecerão dos salarios, que tem os Procuradores, Scrivãos, e Enqueredores, que na Corte andarem, para o que poderá mandar citar as partes, assi na Corte, como fóra della, como pôde fazer o Juiz da Chancellaria na Casa da Supplicação.` },
        { id: 'of1-tvii-28', number: '28', text: `E bem assi conhecerá dos erros dos Scrivães da Corte, e dos Tabelliães e Scrivãos do lugar, onde a Corte stiver, sobre levarem mais salario de suas scripturas, ou buscas, que o conteúdo em seus Regimentos e Ordenações, quando por isso merecerem outra maior pena, que restituirem o que assi mais levarem, sendo-lhe remettidos pelo Chancellor Mór.` },
        { id: 'of1-tvii-29', number: '29', text: `E os ditos Corregedores da Corte tomarão conhecimento per ação nova dos feitos crimes dos moradores das Ilhas, que na Corte forem demandados, por nella serem achados, postoque os delictos fossem commettidos nas Ilhas. E assi quando forem demandados em alguns lugares do Reino por delictos, que em cada hum delles houvessem commettido; porque tanto que forem citados perante quaesquer Justiças, logo devem ser remettidos aos ditos Corregedores da Corte, salvo se dos taes delictos tiverem tomadas Cartas de seguro, porque em tal caso serão remettidos a quem suas Cartas forem dirigidas, postoque na Corte sejam achados. E dos crimes commettidos nas Ilhas, e dos que os moradores dellas commetterem nestes Reinos, tomarão querelas, e por ellas mandarão prender, sendo obrigatoria. Porém não tolhemos que as outras Justiças, que poder tenham de as tomar, o possam fazer, sendo pelas partes requerido, guardando em tudo seu Regimento e nossas Ordenações.` },
        { id: 'of1-tvii-30', number: '30', text: `Quando Nós stivermos apartados da Casa da Supplicação, o Corregedor, que comnosco andar, passará as Cartas das execuções das dizimas das sentenças, que se derem pelos Officiaes, que comnosco andarem. E conhecerá dos feitos dellas com os Desembargadores, que para isso lhe ordenarmos.` },
        { id: 'of1-tvii-31', number: '31', text: `E os Corregedores da Corte poderão avocar a si os feitos dos Juizes do Crime da cidade de Lisboa, sendo da qualidade dos que os Corregedores das Comarcas per seu Regimento podem avocar. E os Corregedores da dita cidade os não avocarão.

32 Item, darão Cartas para as nossas Justiças guardarem as Cartas de seguro, que os Clerigos de Ordens Sacras, ou Beneficiados houvessem de seus Prelados, sendo-lhes pelas partes requerido. E bem assi, quando pelos Clerigos, ou Beneficiados lhes for requerido, que lhes mandem guardar as sentenças, per que forem livres diante seus Juizes, passar-lhes-hão para isso nossa Carta, como se dirá no Livro segundo, Titulo primeiro.` },
        { id: 'of1-tvii-32', number: '33', text: `Item, aos Corregedores da Corte pertence tomar querelas das mulheres solteiras no lugar, onde stiver a Corte, e na cidade de Lisboa, por serem amancebadas com pessoas, a que per bem de nossas Ordenações pelo dito caso são postas penas.

E serão Juizes dos ditos casos, e as despacharão em Relação. E outro algum Julgador não tomará as ditas querelas, nem serão presas as taes pessoas, senão per mandado dos ditos Corregedores, sob pena da pessoa, que perante outro Julgador as demandar, pagar dez cruzados, ametade para o accusador, e a outra para as despesas da Relação.` },
        { id: 'of1-tvii-33', number: '34', text: `E quando Nós stivermos apartados da Casa da Supplicação, o Corregedor do Crime, que comnosco andar, conhecerá das causas civeis, usando do Regimento dos Corregedores dos feitos civeis da Corte. E quando Nós partirmos do dito lugar, deixará os feitos no dito lugar, e guardará a fórma, que he dada aos Corregedores das Comarcas.` },
        { id: 'of1-tvii-34', number: '35', text: `Item, quando algum nosso morador, que andar em nossos livros, e for Clerigo de Ordens Menores, ou Sacras, ou Beneficiado, commetter algum crime em qualquer lugar de nossos Reinos e senhorios, responderá perante o Corregedor da Corte, quanto ao civel, que descender de alguns danos, ou crimes per elle commettidos, para satisfação da parte, como diremos no segundo Livro, no Titulo 4: Quando os moradores da Casa del Rei, etc.` },
        { id: 'of1-tvii-35', number: '36', text: `Item, o dito Corregedor, quando nossa Corte se houvela muar de qualquer cidade, ou villa, mande pregoar per quinze dias antes, que qualquer pessoa, a quem tiverem tomadas casas, ou camas por aposentadoria, que algum dano tiver recebido dos que nellas pousaram, se vá ao Serivão dante elle, que lhe vá ver os danos das ditas casas, ou camas, ao qual mandamos, que tanto que lhe requerido for, vá a isso. E sendo-lhe mostrado o dano, que lhe fizeram, e afirmando per juramento, que lhe será dado pelo Serivão, lh'o faça avaliar per dous Officiaes juramentados, para lhe ser pago per mandado do dito Corregedor.` },
      ],
    },
    {
      id: 'titulo-viii',
      title: `VIII. Des Corregedores da Corte dos feitos civeis`,
      type: 'articles',
      articles: [
        { id: 'of1-tviii-preambulo', number: 'Preâmbulo', text: `Os Corregedores da Corte dos feitos civeis usarão inteiramente de todo o Regimento, que temos ordenado aos Corregedores das Comarcas, em quanto não contradisser ao que se contém em este Regimento, specialmente a elles dado, não tocando em causas crimes. E farão os ditos Corregedores cada hum em huma semana dous dias audiencias publicas; convem saber, á segunda-feira, e á quinta á tarde; e as não commetterão a outrem. E sendo impedidos, o farão saber ao Regedor, para prover confórme a seu Regimento.` },
        { id: 'of1-tviii-1', number: '1', text: `Item, tomarão conhecimento geralmente no lugar, onde a Casa da Supplicação stiver, e a cinco legoas ao redor, per auçào nova, de todas as causas civeis. E de fóra das cinco legoas poderão mandar citar nos casos da Lei Diffamari a requerimento da parte, que morar no lugar, onde a Corte, ou Casa da Supplicação stiver, ou cinco legoas ao redor, como se dirá no Livro terceiro, Titulo 11: Dos que podem ser citados perante os Juizes Ordinarios, etc.` },
        { id: 'of1-tviii-2', number: '2', text: `E nem os feitos civeis, que a seu Officio pertencem, desembargal-os-hão fóra da Relação, por se não tolher o aggravo delles para os Desembargadores dos Aggravos; salvo se per nossa special Provisão lhes concedermos, que os despachem em Relação. E da sentença definitiva, que elles per si sós derem, as partes, que se sentirem aggravadas, poderão aggravar; e sejam-lhes recebidos os aggravos, se não couberem em sua alçada, que he até oito mil réis em bens de raiz, e dez nos bens mo- veis, afóra as custas. E das interlocutorias, ou mandados, que nos ditos feitos pozerem, poderão aggravar per petição à Relação nos casos, que dissemos no Titulo 6: Dos Desembargadores dos Aggravos, e diremos no Livro 3 Titulo 20: Da ordem do Juizo. E nos outros casos poderão aggravar no auto do processo.` },
        { id: 'of1-tviii-3', number: '3', text: `Item, tomarão conhecimento de todos os feitos civeis, per nova aução, dos Prelados isentos, que nestes Reinos não tem Superior Ecclesiastico, que de seus feitos possa conhecer, como se contém no segundo Livro, no Titulo primeiro.` },
        { id: 'of1-tviii-4', number: '4', text: `Darão cartas para serem citadas quaesquer pessoas, que tiverem jurisdição, ou lugares de senhorio, quando os autores os quizerem perante elles demandar, não sendo cousas, que pertençam ao Juizo dos nossos Feitos da Coroa, ou Fazenda.` },
        { id: 'of1-tviii-5', number: '5', text: `Conhecerão de todos os feitos civeis, que per nosso special mandado vierem à Corte per remissão, antes da sentença definitiva, dante quaesquer Julgadores, e nos casos, em que por nossas Ordenações expressamente lhes dermos lugar, que os ditos Julgadores os remettam.` },
        { id: 'of1-tviii-6', number: '6', text: `E tomarão conhecimento de feitos civeis das viuvas e orfãos, e pessoas miseraveis, e de outras pessoas, que tem semelhante privilegio, se os escolherem por Juizes; por quanto tem privilegio de perante elles demandarem, ou se defenderem, quando em seu Juizo quizerem litigar. E dos feitos das mais pessoas conteúdas no Livro terceiro, Titulo quinto e seis e doze, como ahi he declarado.` },
        { id: 'of1-tviii-7', number: '7', text: `E darão Cartas para os Desembargadores da Casa da Supplicação trazerem seus contendores perante elles, donde quer que forem moradores, aindaque seja sobre quererem demandar algumas pessoas, por lhes irem contra seus privilegios, ou sobre os encoutos em casos, que não toquem a Direitos Reaes, porque tocando a elles, pertence o conhecimento ao Juizo dos nossos feitos.` },
        { id: 'of1-tviii-8', number: '8', text: `E per aução nova conhecerão dos feitos dos moradores das Ilhas, que forem demandados na Corte, ou na Casa da Supplicação, por serem achados nella, postoque os contractos sejam feitos nas Ilhas. E assi quando forem demandados em alguns lugares do Reino por contractos, que nelles tenham feitos, ou per razão de cousas situadas nos ditos lugares do Reino; porque tanto que forem citados perante quaesquer Juizes, logo devem ser remetidos aos ditos Corregedores da Corte na Casa da Supplicação; os quaes conhecerão delles, e os determinarão finalmente pela ordem, que despacham os outros feitos.` },
        { id: 'of1-tviii-9', number: '9', text: `Outrosi conhecerão de quaesquer aggravos, que a elles vierem de feitos civeis per petição dante os Julgadores no lugar, onde stiver a Casa da Supplicação, e ao redor até cinco legoas (não sendo dante os Julgadores da cidade de Lisboa); e do que elles nos ditos aggravos mandarem, poderão as partes aggravar para os Desembargadores dos Aggravos. E dos aggravos dos ditos feitos civeis, que vierem per instrumentos, ou Cartas testemunhaveis, de qualquer lugar, postoque seja dentro das cinco legoas, conhecerão os Desembargadores dos Aggravos, e não os Corregedores.` },
        { id: 'of1-tviii-10', number: '10', text: `E mandamos aos ditos Corregedores, que em todas as Cartas, que passarem, para se haverem de fazer algumas execuções, ou diligencias, as passem na fórma e com as clausulas, que dissemos no Titulo 7: Dos Corregedores da Corte dos feitos crimes, no paragrapho 23: Outrosi mandamos.` },
      ],
    },
    {
      id: 'titulo-ix',
      title: `IX. Dos Juizes dos feitos del Rei da Coroa`,
      type: 'articles',
      articles: [
        { id: 'of1-tix-preambulo', number: 'Preâmbulo', text: `Aos Juizes dos nossos feitos da Coroa pertence conhecer em Relação per aução Encouto, multa ou pena pecuniaria imposta por leis antigas, prohibindo o uso de determinada cousa.

nova e per petição de aggravo na cidade de Lisboa, onde a Casa da Supplicação reside, e cinco legoas ao redor, e de fóra da Corte dos lugares e Comarcas do districto da Casa da Supplicação per appelação e per instrumentos de aggravo, ou Cartas testemunhaveis, de todos os feitos e demandas, que pertencem à Coroa dos nossos Reinos, assi per razão de Reguengos, como de Jugadas, e de todos os outros bens, que a Nós pertencem. E assi, sobre Dizimas, Portagens e outros quaesquer Direitos Reaes, postoque dos ditos bens e Direitos tenhamos feito mercê a algumas pessoas. E isto aindaque sejam demandados com nome e qualidade de força, ou per qualquer outra maneira, salvo nos feitos das Sisas, e das rendas, fóros e tributos, que se para Nós arrecadam; porque nestes casos, quando se não tratar sobre a propriedade delles, mas sómente sobre as rendas, conhecerão os Juizes dos nossos feitos da Fazenda. E em todos os casos sobreditos os ditos Juizes conhecerão, aindaque seja entre partes, se direitamente a esse tempo, ou depois tocarem nossos direitos, e a elles possam trazer algum proveito, ou dano. Porque se a demanda for entre partes, que não neguem nossos Direitos, não pertence o conhecimento do tal caso aos Juizes dos nossos feitos da Coroa.` },
        { id: 'of1-tix-1', number: '1', text: `E não tolhemos, se os autores antes quizerem demandar as partes perante os Juizes, a que pertencia o conhecimento, se ahi não stivera a Corte e Casa da Supplicação, que as possam perante elles demandar. E as appellações e aggravos virão aos Juizes dos nossos feitos.

Erão o que constituia a sua dotação ou lista civil. Estes bens tinhão muitos privilegios.` },
        { id: 'of1-tix-2', number: '2', text: `E per instrumentos de aggravo, ou Cartas testemunhaveis, não darão determinação final em casos sobre jurisdição, ou Direitos Reaes, assi ácerca da posse, como da propriedade. Sómente poderão dar determinação ácerca das interlocutorias, de que couber aggravo. Porém as pessoas, que tiverem doações de jurisdições, ou Direitos Reaes, poderão vir com embargos aos mandados e despachos, e autos, que as Justiças fizerem, parecendo-lhes que são contra as ditas doações, ou posse, que pretenderem ter nas ditas jurisdições, ou Direitos. E sendo-lhes os embargos recebidos pelas ditas Justiças, o Procurador de nossos feitos, ou Almoxarife, que na terra stiver, poderão contrariar os ditos embargos. E depois de se tratar por esta maneira o caso perante as ditas Justiças, e elles o determinarem finalmente, sendo a determinação final sobre a posse, ou sobre a propriedade, poderão as ditas pessoas appellar das sentenças finaes, sendo o caso de appellação. E sendo as sentenças dadas contra o Procurador dos nossos feitos, que na terra stiver, elle, ou o Almoxarife appellarão dellas, e as taes appellações virão ao Juiz dos nossos feitos, onde se determinarão e se cumprirão as sentênças, que nelle forem dadas: e não recebendo as Justiças os taes embargos, ou pondo no processo delles alguma interlocutoria, de que haja lugar aggravo, poderão as ditas partes aggravar, e tirar instrumentos para os Juizes dos nossos feitos, onde se pronunciará o que for justiça ácerca das interlocutorias sómente, sem darem pelos ditos instrumentos final determinação nos ditos casos; e dando-se, será nenhuma e de nenhum vigor. E os taes instrumentos, que ao Juiz de nossos feitos vierem, não se despacharão, sem se dar vista ao nosso Procurador.` },
        { id: 'of1-tix-3', number: '3', text: `E nos instrumentos, de que o conhecimento pertencer ao Juizo dos nossos feitos, se não dará determinação final, sem o nosso Procurador ácerca disso ser ouvido ordinariamente. E dando-se em outra maneira a sentença, per que o caso seja finalmente determinado, será nenhuma e de nenhum effeito. Porém, sendo o tal instrumento tirado sobre alguma interlocutoria, não sendo das que se contém no paragrapho precedente, despachar-se-ha, como for justiça, no que sómente tocar à tal interlocutoria, não tendo força de definitiva, sem ser necessario dar-se vista ao dito Procurador.` },
        { id: 'of1-tix-4', number: '4', text: `Não tomarão conhecimento dos feitos, que se tratarem entre partes sobre prazos, que os Donatarios dos Reguengos fazem, se se podem vender, ou não, em prejuizo dos filhos mais velhos; porque não se tratando de prejuizo consideravel, que possa vir à nossa Coroa, não pertence o conhecimento ao Juizo dos nossos feitos, mas ao dos Aggravos.` },
        { id: 'of1-tix-5', number: '5', text: `E conhecerão de todos os feitos, que os Rendeiros das Sisas da casa das herdades de Lisboa tiverem com os Commendadores e Cavalleiros da Ordem de Nosso Senhor Jesus Christo, sobre se quererem escusar de pagar Sisa das propriedades, que compram, ou vendem.` },
        { id: 'of1-tix-6', number: '6', text: `E pelo dito modo conhecerão de todos os feitos, postoque sejam entre partes, que se ordenarem per razão de doações per Nós feitas, assi de bens, que a Nós pertençam de algum, que morreu abintestado, ou outros quaesquer vagos, ou outras cousas, a Nós devolutas por quaesquer causa, de que fizessemos mercê, ou doação a algumas pessoas.` },
        { id: 'of1-tix-7', number: '7', text: `Item, conhecerão em Relação de todos os feitos de passadores.` },
        { id: 'of1-tix-8', number: '8', text: `E não mandarão vir citadas à Corte nenhumas partes de fóra da Corte, e de cinco legoas ao redor, até primeiro serem vistas em Relação as informações, ou inquirições, per que entendam, que devem ser citadas. E quando fôr acordado per a maior parte dos Desembargadores, que com cada hum delles forem no despacho, então dêm Cartas, per que citem, segundo fôr acordado e posto per desembargo. Porém, se as citações se houverem de fazer para as partes virem fallar a feitos, que já sejam tratados perante elles, poderão per si sós mandar passar as Cartas sem acordo da Relação.` },
        { id: 'of1-tix-9', number: '9', text: `E tomarão conhecimento dos instrumentos de aggravo, ou Cartas testemunhaveis, que os Desembargadores e mais pessoas privilegiadas tirarem de lhes não guardarem seus privilegios, quando os ditos instrumentos tocarem a cousas de Jugadas, ou de quaesquer outros Direitos Reaes. Porque dos instrumentos que não tocarem aos ditos Direitos Reaes, tomarão conhecimento os Desembargadores dos Aggravos.` },
        { id: 'of1-tix-10', number: '10', text: `Não tomarão conhecimento de instrumentos de aggravo, que alguns Mareantes, ou Pescadores tirarem de serem constrangidos a servir em nossas Armadas, per mandado dos Védores da Fazenda, ou de quaesquer outros nossos Officiaes, nem de os obrigarem a ter armas; e pretendendo haverem de ser escusos per razão de seus privilegios, poderão requerer sobre elles aos ditos Védores da Fazenda.` },
        { id: 'of1-tix-11', number: '11', text: `Outrosi conhecerão das causas sobre as jurisdições, e de quaesquer feitos e cousas, que a elles pertençam. E assi de instrumentos de aggravo, ou Cartas testemunhaveis, que se tirarem dante os Juizes seculares, que se derem por inhibidos pelas inhibitorias dos Juizes Ecclesiasticos, dos quaes não tomarão conhecimento os Desembargadores dos Aggravos.` },
        { id: 'of1-tix-12', number: '12', text: `Porém não tomarão conhecimento de aggravo, que as partes tirarem de Juizes Ecclesiasticos nos casos, de que o conhecimento lhes pertence; salvo quando se aggravarem de notoria oppressão, ou força, que se lhes faça, ou de se lhes não guardar o Direito Natural, porque nestes casos Nós, como Rei e Senhor, temos obrigação de acudir a nossos Vassallos. E depois de os Juizes de nossos feitos julgarem, que o conhecimento pertence a nossas Justiças, e não ás Ecclesiasticas, mandarão ás nossas Justiças, que não evitem as taes pessoas, nem lhes levem penas de excommuningados, por sempre assi se costumar, e não haver outro meio para se não tomar nossa jurisdição.` },
        { id: 'of1-tix-13', number: '13', text: `E tomarão conhecimento das causas tocantes á apresentação das Igrejas do nosso Padroado, que se houvessem de tratar no Juizo secular, postoque sejam do districto da Relação do Porto.` },
        { id: 'of1-tix-14', number: '14', text: `Outrosi, os Juizes dos nossos feitos tomarão conhecimento de todas as appellações de armas, e penas dellas. E assi das appellações de condenação da pena, e perdimento de armas depois do sino, e dos aggravos das ditas armas, e penas dellas, assi da Corte e cidade de Lisboa, como de fóra della, salvo dos aggravos, que das ditas armas e penas vierem dante o Corregedor da Corte dos feitos crimes, porque destes pertence o conhecimento aos Desembargadores dos Aggravos, segundo dissemos no Titulo 7: Dos Corregedores da Corte dos feitos crimes.` },
        { id: 'of1-tix-15', number: '15', text: `Outrosi, darão Cartas, que pertençam ás abertas e Valladores nossos, e conhecerão dos feitos, que ás ditas abertas e vallas pertencerem. E assi conhecerão dos feitos, que se processarem sobre as terras das Lezirias, e Paúes nossos, ora o nosso Procurador seja parte, ora não, postoque dellas tenhamos feito mercê a algumas pessoas.` },
        { id: 'of1-tix-16', number: '16', text: `E os feitos, que em outros quaesquer Juízos se tratarem, assi na Corte, como fóra della, em que o Procurador dos nossos feitos da Casa da Supplicação se oppozer, ou assistir, serão logo remetidos nos termos, em que stiverem, aos Juizes dos nossos feitos, dos quaes tomarão conhecimento, e os despacharão em Relação. E isto se não entenderá nos feitos, que vierem per aggravo dante o Juiz da India e Mina, por quanto o conhecimento destes taes feitos pertence aos Desembargadores dos Aggravos da Casa da Supplicação, postoque delles se mande dar vista ao Procurador dos nossos feitos, e nelles allegue por nossa parte. E conhecerão dos aggravos, que vierem do Juizo da Coroa da Casa do Porto, e os despacharão em Relação, como despacham os mais feitos, que lhes pertencem.` },
        { id: 'of1-tix-17', number: '17', text: `E despacharão em Relação os feitos e instrumentos, que lhes pertencerem, com os Desembargadores, que pelo Regedor lhes forem ordenados. E porão nelles as sentenças e desembargos, segundo per todos, ou a maior parte delles fôr acordado, sem haver outro aggravo para nenhuma outra parte. E nos feitos, em que o nosso Procurador for parte, serão pelo menos três confórmes, como se dirá nos feitos da Fazenda, no Titulo 10: Dos Juizes dos feitos della.` },
        { id: 'of1-tix-18', number: '18', text: `E mandamos, que os Juizes dos nossos feitos da Coroa em todas as Cartas, que passarem, para se haverem de fazer algumas execuções, ou diligencias, as passem na fórma e com as clausulas, que dissemos no Titulo 7: Dos Corregedores da Corte dos feitos crimes, no paragrapho 23: Outrosi mandamos.` },
      ],
    },
    {
      id: 'titulo-x',
      title: `X. Dos Juizes dos feitos del Rei da Fazenda`,
      type: 'articles',
      articles: [
        { id: 'of1-tx-preambulo', number: 'Preâmbulo', text: `Os Juizes dos feitos da Fazenda despacharão em Relação pela maneira, que dissemos no Titulo 9: Dos Juizes dos feitos da Coroa, os feitos e instrumentos de aggravo, que pertencem a nossa Fazenda. E naquelles, em que o nosso Procurador da Fazenda for parte, se não porá sentença, salvo havendo tres votos confórmes em hum parecer. E havendo variedade nos votos, se darão tantos Juizes, de que a mór parte seja ao menos de tres votos confórmes. E na dita sentença assinarão tambem os Desembargadores, que fôrem de voto contrário. E nos feitos entre partes se porá sentença, como fôrem dous votos confórmes. E não porão differença alguma nos sinaes, per que se possa saber, que foram de contrário parecer em parte, ou em todo. E tendo os ditos Juizes para despachar alguns feitos do negocio dos Contos, os despacharão primeiro, que outros alguns.` },
        { id: 'of1-tx-1', number: '1', text: `E despacharão assi mesmo os feitos da Fazenda, assi do negocio do Reino, como da India, Africa e Contos, e assi os feitos da Fazenda, que se tratarem entre partes, civeis e crimes, e instrumentos de aggravo, para o despacho dos quaes o Regedor lhes ordenará huma, ou duas mesas, com os Desembargadores, que lhe parecer serem necessários, segundo a qualidade dos negocios e feitos, que tiverem para despachar. E ao despacho dos feitos, em que o nosso Procurador da Fazenda for parte, stará sempre presente. Mas não tomarão conhecimento dos instrumentos de aggravo, que se tirarem dos Officiaes e Lançadores, que repartem as Sisas dos encabeçamentos, nem assi mesmo dos que se tirarem sobre a ordem e recadação dellas. Porque o conhecimento dos taes instrumentos e despacho delles pertence aos Védores da Fazenda: postoque as partes se queiram per privilegios, que digam ter, isentar na dita repartição de pagar Sisa em todo.

Mas as Relações conhecem dos aggravos e appellações nas causas que respeitão ao Thesouro Nacional, com assistência do Procurador da Corôa e Soberania, que he tambem da Fazenda Nacional. Era a antiga pratica.` },
        { id: 'of1-tx-2', number: '2', text: `E conhecerão dos feitos, que se tratarem entre algumas pessoas sobre Officios, de que forem passadas Cartas, assignadas per Nós, ou pelos Védores de nossa Fazenda, e os despacharão em Relação, da maneira que despacham os mais feitos, de que o conhecimento lhes pertence, e haverá delles vista o Procurador dos nossos feitos da Fazenda.` },
        { id: 'of1-tx-3', number: '3', text: `E sendo necessário para despacho dos ditos feitos fazerem-se algumas diligencias nos Contos do Reino e Casa, e nas Casas da India, Mina e Armazens, e na Alfandega da cidade de Lisboa, e em quaesquer outras casas, onde se recadem nossos Direitos na dita cidade, ou dar alguns papeis, ou certidões dos livros dellas, ou responderem os Officiaes dos Contos e das ditas Casas algumas cousas, pertencentes ao despacho dos ditos feitos, e que nelles se mandem fazer e ajuntar, assi per despacho, posto per acordam em Relação, como per mandado em audiencia pelos ditos Juizes sómente: passarão para isso Precatorios, dirigidos ao Contador Mór e Provedores, e mais Officiaes Superiores das ditas Casas, na fórma, em que os Corregedores da Corte os passam para os ditos Provedores e Officiaes Superiores. E a mesma ordem terão nos Precatorios, que passarem para o Provedor das Valias e Contador das Jugadas, Lezirias e Paues. E sendo passados na dita fórma, os cumprirão os ditos Officiaes inteiramente, como per nossas Ordenações são obrigados.` },
        { id: 'of1-tx-4', number: '4', text: `E havendo-se de ajuntar alguns traslados de Regimentos, Provisões, ou outras quaesquer cousas, que stiverem registradas nos livros da Fazenda, que se hajam de dar delles, feitos pelos Porteiros della, o Juiz do feito passará Precatorio na fórma acostumada, dirigido aos Védores da Fa- zenda, para mandarem dar os ditos traslados, por quanto dos livros da nossa Fazenda não se deve dar traslado algum sem mandado dos Védores della.` },
        { id: 'of1-tx-5', number: '5', text: `Item, os ditos Juizes tomarão conhecimento per simplices petições dos aggravos que as partes disserem, que lhes fazem os Officiaes, de que os ditos Juizes podem conhecer per appellação, ou aggravo. E isto sómente, aggravando-se do despacho, que alguns Officiaes pozerem em alguns feitos, ou sobre o que mandarem nas audiencias.` },
        { id: 'of1-tx-6', number: '6', text: `E não conhecerão das petições, em que as partes se aggravarem dos Almoxarifes, ou outros alguns Officiaes os obrigarem a pagar direitos de cousas, que não devem, ou mais daquelles, que devem, ou de lhes não guardarem ácerca disso os privilégios, que tiverem, ou lhes não fazerem pagamento de suas tenças, ou dinheiro, que de nossa Fazenda hão de haver, ou tratando-se nas ditas petições da jurisdição de alguns feitos da Fazenda: por quanto o conhecimento e despacho das taes petições pertence ao Tribunal do Conselho da Fazenda. E o mesmo será nas appellações e instrumentos de aggravo, que se tirarem sobre os ditos casos.` },
        { id: 'of1-tx-7', number: '7', text: `E havendo por bem que alguns feitos do dito Juizo se despachem perante Nós, será presente ao despacho delles o Védor da Fazenda, que servir.` },
        { id: 'of1-tx-8', number: '8', text: `E assi tomarão conhecimento de todos os feitos, em que o Procurador de nossa Fazenda se oppozer, ou assistir, e lhes serão remetidos, tanto que o dito Procurador se oppozer, ou assistir, sem mais Juiz algum tomar delles conhecimento, assi em todos os Juizes da Corte, como de todos nossos Reinos e Senhorios.` },
        { id: 'of1-tx-9', number: '9', text: `Item, conhecerão das appellações e aggravos, que saírem dante o Provedor e Officiaes da Alfandega de Lisboa, sobre descaminhados das mercadorias e cousas, que á dita Alfandega pertencem, passando a quantia de sessenta mil réis, sendo appellado pelas partes condenadas, ou pelo Procurador dos feitos da dita Alfandega; ao qual mandamos que sempre appelle por parte de nossa Fazenda nos ditos feitos, não sendo as partes condenadas em tudo o que contra ellas pedir, para o que os Scrivaes dos ditos feitos lhe notificarão as sentenças. E não passando a quantia de sessenta mil réis, não entrando nisso a pena do dobro ou tresdobro, terá alçada o dito Provedor e Officiaes sem appellação e aggravo. E quanto á pena crime, em que as partes encorrem por os ditos descaminhados, ou por outros delictos, que sobre cousas e direitos da dita Alfandega se commetterem, não tomará o Provedor e Officiaes conhecimento; mas logo remeterão os taes feitos aos Juizes da Fazenda, para elles os despacharem em Relação.` },
        { id: 'of1-tx-10', number: '10', text: `E os ditos feitos, de que assi podem conhecer per appellação e aggravo, por passarem de sessenta mil réis, poderão ser avocados pelos ditos Juizes em quaesquer termos, em que stiverem, parecendo-lhes que ha justas causas para isso. E não passando da quantia de sessenta mil réis, não poderão ser avocados pelos ditos Juizes antes da sentença, nem depois della.` },
        { id: 'of1-tx-11', number: '11', text: `E para se saber, se a valia dos descaminhados chega á quantia dos sessenta mil réis sem a pena do dobro e tresdobro, fará o Provedor da Alfandega fazer avaliação delles por dous mercadores sem suspeita, hum, em que se elle para isso louvará, e outro, em que se louvarão as partes; aos quaes o Provedor dará juramento dos Santos Evangelhos, e pelo dito juramento farão a dita avaliação, de que se fará termo nos autos, assinado per elles, para se saber se cabe na alçada do Provedor e Officiaes, ou se se póde appellar de sua determinação, como atraz he declarado. E não concordando os dous louvados, se louvarão em terceiro, que o determine. E o que os ditos dous louvados assentarem, isso se cumprirá ácerca da dita avaliação.` },
        { id: 'of1-tx-12', number: '12', text: `Item, conhecerão de todos os feitos de injurias feitas, ou ditas aos Rendeiros de nossas rendas, ou Officiaes dellas, sobre a recadação de nossas rendas, ou sobre seus Officios, per aução nova na Corte e A edição Vicentina usa da expressão — fasem pagamento — em lugar de — faserem.

Casa da Supplicação, ou fóra della cinco legoas ao redor, quer sejam autores, quer reos: e per appellação, quando vierem dante algum Contador, ou Almoxarife. Porém tratando-se os feitos sobre os ditos casos ante os Julgadores ordinarios, as appellações, que delles saírem, irão aos Ouvidores dos feitos crimes, e não aos Juizes de nossos feitos.` },
        { id: 'of1-tx-13', number: '13', text: `E conhecerão de todos os feitos e causas, assi crimes, como civeis, em que per o Procurador de nossos feitos da Fazenda forem accusados, ou demandados, por commeterem casos, ou culpas contra seus Regimentos e obrigações de seus Carregos, os Officiaes das Casas da India Mina e Armazens, e Capitães, Scrivães, Mestres, Pilotos das Naos da India, Mina, Guiné, Angóla, Brasil, Capitães das Fortalezas, Alcaides Mores, Juizes das Alfandegas, Feitores, Almoxarifes, Recebedores e Scrivães dos ditos Carregos das partes da India, Mina, Guiné, Angóla e Brasil. E conhecerão outrosi das culpas das devassas, que lhe o Juiz da Mina per bem de seu Regimento he obrigado remetter, e as despacharão em Relação: e procurará nos ditos feitos o Procurador de nossa Fazenda.` },
        { id: 'of1-tx-14', number: '14', text: `E os feitos, que se tratarem contra os Officiaes da Fazenda, por culpas, ou erros de seus Officios, se despacharão, assi o que toca ao crime, como ao civel, pelos Juizes da Fazenda. E isto se não entenderá, quando as appellações vierem dos Corregedores, Ouvidores e Juizes do Reino, porque vindo dante elles, pertence o conhecimento ao Juiz da Chancellaria, como em seu Titulo 14 se dirá.` },
        { id: 'of1-tx-15', number: '15', text: `Item, tomarão conhecimento das appellações e aggravos, que saírem dante as Justiças e Officiaes, que conhecem dos feitos da Fazenda da Universidade de Coimbra, entre a dita Universidade e os Rendeiros e Recebedores, Fiadores e Abonadores de suas rendas, e quaesquer outras pessoas.` },
        { id: 'of1-tx-16', number: '16', text: `Tomarão outrosi conhecimento das causas que tocarem aos nossos Armazens da cidade de Lisboa, as quaes desembargarão pela ordem acima dita, sendo as taes causas sobre a renovação dos prazos dos ditos Armazens, ou arrecadação dos fóros delles; porque tratando-se da propriedade dos ditos prazos e validade dos titulos delles, ou commissos, ou sobre se haver de tomar posse per nossa parte, por serem as vidas acabadas, em taes casos pertence o conhecimento ao Juiz dos nossos feitos da Coroa.` },
        { id: 'of1-tx-17', number: '17', text: `E sendo caso, que Nós por algum respeito mandemos, que alguns feitos da Fazenda se despachem perante os Védores della, os Juizes, que forem dos ditos feitos, os irão despachar ao Conselho da Fazenda; e nem por isso deixarão de ficar ordinarios de seu Juizo, como eram, nem se mudará a natureza delles, para se poder dizer, que são de sportulas, mas levarão sómente a assinatura direita.` },
        { id: 'of1-tx-18', number: '18', text: `E mandamos aos ditos Juizes da Fazenda, que em todas as Cartas, que passarem, para se haverem de fazer algumas execuções, ou diligencias, as passem na fórma e com as clausulas, que dissemos no Titulo 7: Dos Corregedores da Corte dos feitos crimes, no paragrapho 23: Outrosi mandamos.` },
      ],
    },
  ],
};
